                renderedOptionsRevision: this.renderOptionsRevision,
                instance,
            } satisfies CodeViewDiffItemContext<LAnnotation, Caret>;
        }
        const instance = new VirtualizedFile<LAnnotation, Caret>(this.createFileOptions(input.id), this, itemMetrics, this.workerManager, this.isContainerManaged);
