            this.idToItem
                .get(prevSelection.id)
                ?.instance.setSelectedLines(null, { notify: false });
        }
        this.selectedLines = selection;
        this.idToItem
            .get(selection?.id ?? '')
            ?.instance.setSelectedLines(selection?.range ?? null, options);
