            try {
                record.dispose();
            }
            catch (error) {
                if (!failed) {
                    failed = true;
                    failure = error;
                }
            }
            // Settling rerendered the instance with whatever the session decided;
            // its height may have changed.
            const item = this.idToItem.get(record.state.id);
            if (item != null) {
                this.markItemLayoutDirty(item);
            }
