        this.height = this.root?.getBoundingClientRect().height ?? 0;
        return this.height;
    }
    public getScrollHeight(): number {
        return this.scrollHeight;
    }
    private flushSlotCoordinator(): void {
        if (this.slotCoordinator == null) {
