            workerManager == null ||
            !workerManager.isWorkingPool() ||
            fileDiff.cacheKey == null ||
            isDiffPlainText(fileDiff)) {
            return;
        }
        const tokenizeMaxLength = this.options.tokenizeMaxLength ?? DEFAULT_TOKENIZE_MAX_LENGTH;
        if (Math.max(fileDiff.additionLines.length, fileDiff.deletionLines.length) >
            tokenizeMaxLength) {
            return;
        }
