    }
    private ensureEstimatedDiffHeights(fileDiff: FileDiffMetadata | undefined = this.getLayoutDiff()): void {
        if (fileDiff == null) {
            this.cache.estimatedSplitHeight = undefined;
            this.cache.estimatedUnifiedHeight = undefined;
            return;
        }
        if (this.cache.estimatedSplitHeight != null &&
            this.cache.estimatedUnifiedHeight != null) {
            return;
        }
        const { disableFileHeader = false, expandUnchanged = false, collapsedContextThreshold = DEFAULT_COLLAPSED_CONTEXT_THRESHOLD, } = this.options;
        const { splitHeight, unifiedHeight } = computeEstimatedDiffHeights({
            fileDiff,
            metrics: this.metrics,
            disableFileHeader,
            hunkSeparators: this.getHunkSeparatorType(),
            expandUnchanged,
            expandedHunks: this.hunksRenderer.getExpandedHunksMap(),
            collapsedContextThreshold,
            canHydratePartialDiff: canHydrateCollapsedContext(fileDiff, this.options.loadDiffFiles != null),
        });
        this.cache.estimatedSplitHeight = splitHeight;
        this.cache.estimatedUnifiedHeight = unifiedHeight;
    }
    private validateComputedHeight(fileDiff: FileDiffMetadata | undefined = this.getLayoutDiff()): void {
