        const hasFileInput = fileInput != null;
        const oldFile = fileInput?.oldFile;
        const newFile = fileInput?.newFile;
        const filesDidChange = hasFileInput &&
            (!areOptionalFilesEqual(oldFile, this.deletionFile) ||
                !areOptionalFilesEqual(newFile, this.additionFile));
        let nextFileDiff = fileDiff ?? this.fileDiff;
        if (fileDiff == null &&
            hasFileInput &&
            (filesDidChange || this.fileDiff == null)) {
            nextFileDiff = parseDiffFromFile(fileInput.oldFile, fileInput.newFile, this.options.parseDiffOptions);
        }
        const { forceRenderOverride, isSetup } = this;
        this.forceRenderOverride = undefined;
        const targetChanged = nextFileDiff != null && !areDiffTargetsEqual(this.fileDiff, nextFileDiff);
        const dataChanged = targetChanged || filesDidChange;
        fileContainer = this.getOrCreateFileContainer(fileContainer);
        if (nextFileDiff == null) {
            console.error('VirtualizedFileDiff.render: attempting to virtually render when we dont have the correct data');
            return false;
        }
        if (targetChanged) {
            this.updateExternalDiff(nextFileDiff, lineAnnotations);
        }
        const { pendingRenderDiff, layoutDiffChanged, renderedDiffChanged, annotationsChanged, } = (() => {
            if (this.pendingRender != null &&
                this.pendingRender.latestDiff ===
