            : this.#diffs.get<LAnnotation>(editStateKey)) as EditState<EType, LAnnotation> | undefined;
    }
    /** Clear a dormant session, returning false when it is active or missing. */
    clear(type: EditorType, editStateKey: string, parts?: ClearEditStateOptions): boolean {
        return type === 'file'
            ? this.#files.clear(editStateKey, parts)
            : this.#diffs.clear(editStateKey, parts);
    }
