        // scanning or splitting every configured shortcut.
        for (const entry of keymap) {
            for (const shortcut of Object.keys(entry.bindings) as EditorShortcut[]) {
                const command = entry.bindings[shortcut];
                if (command === undefined) {
                    continue;
