                const linewise = command === 'toggleComment';
                const result = resolveBlockCommentEdits(textDocument, selections, blockComment, linewise);
                if (result !== undefined) {
                    this.#applyCommandEdits(result.edits, linewise
                        ? undefined
                        : (document) => result.nextSelectionOffsets.map(([start, end, direction]) => ({
                            start: document.positionAt(start),
                            end: document.positionAt(end),
                            direction,
                        })));
