                    break;
                }
                const lineNumber = getLineNumberAttr(child);
                const lineType = child.dataset.lineType;
                if (lineNumber !== undefined &&
                    lineNumber === line + 1 &&
                    lineType !== undefined &&
                    isLineEditable(lineType)) {
                    lineElement = child;
                    break;
                }
