export function attachResolvedThemes(themes: DiffsThemeNames | ThemeRegistrationResolved | (DiffsThemeNames | ThemeRegistrationResolved)[], highlighter: DiffsHighlighter): void {
    themes = Array.isArray(themes) ? themes : [themes];
    for (let themeRef of themes) {
