                    this.renderCache.result == null)) {
                const { result, options } = this.renderDiffWithHighlighter(diff, this.highlighter, forcePlainText || !hasLangs);
                this.renderCache = {
                    diff,
                    options,
                    highlighted: canHighlight,
                    result,
                    renderRange: undefined,
                };
            }
            // If we get in here it means we'll have to kick off an async highlight
            // process which will involve initializing the highlighter with new themes
            // and languages
            if (!hasThemes || (!forcePlainText && !hasLangs)) {
                void this.asyncHighlight(diff).then(({ result, options }) => {
                    this.applyHighlightResult(diff, result, options, !forcePlainText);
                });
            }
        }
        return this.renderCache.result != null
            ? this.processDiffResult(this.renderCache.diff, renderRange, this.renderCache.result)
            : undefined;
    }
    public async asyncRender(diff: FileDiffMetadata, renderRange: RenderRange = DEFAULT_RENDER_RANGE): Promise<HunksRenderResult> {
        this.diff = diff;
        const { result } = await this.asyncHighlight(diff);
        return this.processDiffResult(diff, renderRange, result);
    }
    protected createPreElement(split: boolean, totalLines: number, customProperties?: CustomPreProperties): HASTElement {
        const { diffIndicators, disableBackground, disableLineNumbers, overflow } = this.getOptionsWithDefaults();
        return createPreElement({
            type: 'diff',
            diffIndicators,
            disableBackground,
            disableLineNumbers,
            overflow,
            split,
            totalLines,
            customProperties,
        });
    }
    private async asyncHighlight(diff: FileDiffMetadata): Promise<RenderDiffResult> {
        const forcePlainText = isDiffMassive(diff, this.getTokenizeMaxLength());
        this.computedLangs = forcePlainText ? ['text'] : getDiffLanguages(diff);
        const hasThemes = this.highlighter != null &&
            areThemesAttached(this.getLocalHighlightTheme());
        const hasLangs = forcePlainText ||
            (this.highlighter != null && areLanguagesAttached(this.computedLangs));
        // If we don't have the required langs or themes, then we need to
        // initialize the highlighter to load the appropriate languages and themes
        if (this.highlighter == null || !hasThemes || !hasLangs) {
            this.highlighter = await this.initializeHighlighter();
        }
        return this.renderDiffWithHighlighter(diff, this.highlighter, forcePlainText);
    }
    private renderDiffWithHighlighter(diff: FileDiffMetadata, highlighter: DiffsHighlighter, forcePlainText = false): RenderDiffResult {
        const { options } = this.getRenderOptions(diff);
        const { collapsedContextThreshold } = this.getOptionsWithDefaults();
        const result = renderDiffWithHighlighter(diff, highlighter, options, {
            forcePlainText,
            expandedHunks: forcePlainText ? true : undefined,
            collapsedContextThreshold,
        });
        if (this.editSessionActive &&
            diff.additionLines.length === 1 &&
            diff.additionLines[0] === '' &&
            result.code.additionLines[0] == null) {
            let fallbackLine: DiffLineMetadata | undefined;
            iterateOverDiff({
                diff,
                diffStyle: 'both',
                expandedHunks: forcePlainText ? true : undefined,
                collapsedContextThreshold,
                callback: ({ additionLine }) => {
                    if (additionLine?.lineIndex !== 0)
                        return;
                    fallbackLine = additionLine;
                    return true;
                },
            });
            if (fallbackLine == null) {
                throw new Error('DiffHunksRenderer: missing empty addition line');
            }
            result.code.additionLines[0] = createPlainAdditionLineElement(0, '', fallbackLine.unifiedLineIndex, fallbackLine.splitLineIndex);
        }
        return { result, options };
    }
    public onHighlightSuccess(diff: FileDiffMetadata, result: ThemedDiffResult, options: RenderDiffOptions, highlighted = true): void {
        if (this.editSessionActive) {
            return;
        }
        this.applyHighlightResult(diff, result, options, highlighted);
    }
    private applyHighlightResult(diff: FileDiffMetadata, result: ThemedDiffResult, options: RenderDiffOptions, highlighted = true): void {
        const { diff: currentDiff, renderCache } = this;
        if (currentDiff == null ||
            renderCache == null ||
            !areDiffTargetsEqual(currentDiff, diff) ||
            !areDiffRenderOptionsEqual(options, this.getRenderOptions(currentDiff).options)) {
            return;
        }
        const triggerRender = renderCache.result == null ||
            !renderCache.highlighted ||
            !areDiffRenderOptionsEqual(renderCache.options, options) ||
            !areDiffTargetsEqual(renderCache.diff, currentDiff);
        if (!triggerRender) {
            return;
        }
        this.pendingHighlightResult = {
            diff: currentDiff,
            options,
            highlighted,
            result,
        };
        this.onRenderUpdate?.();
    }
    private getMatchingWorkerResultCache(diff: FileDiffMetadata, options: RenderDiffOptions): RenderDiffResult | undefined {
        if (this.editSessionActive) {
            return undefined;
        }
        const cache = this.workerManager?.getDiffResultCache(diff);
        if (cache == null || !areDiffRenderOptionsEqual(options, cache.options)) {
            return undefined;
        }
        return cache;
    }
    // Returns completed background work that can replace the rendered AST on
    // the next render. Reading it does not promote or discard pending work.
    private getReadyRenderResult(diff: FileDiffMetadata, options: RenderDiffOptions): PendingHighlightResult | undefined {
        const { pendingHighlightResult } = this;
        if (pendingHighlightResult != null &&
            areDiffTargetsEqual(pendingHighlightResult.diff, diff) &&
            areDiffRenderOptionsEqual(pendingHighlightResult.options, options)) {
            return pendingHighlightResult;
        }
        const workerCache = this.getMatchingWorkerResultCache(diff, options);
        // Return nothing when the worker has not finished, or when this diff is
        // already rendered with matching highlighted markup. In both cases the
        // current render cache should remain unchanged.
        if (workerCache == null || this.hasHighlightedRenderCache(diff, options)) {
            return undefined;
        }
        return { diff, highlighted: true, ...workerCache };
    }
    private hasHighlightedRenderCache(diff: FileDiffMetadata, options: RenderDiffOptions): boolean {
        const { renderCache } = this;
        return (renderCache?.result != null &&
            renderCache.highlighted &&
            areDiffTargetsEqual(diff, renderCache.diff) &&
            areDiffRenderOptionsEqual(options, renderCache.options));
    }
    public onHighlightError(error: unknown): void {
        console.error(error);
    }
    private getTokenizeMaxLength(): number {
        return this.options.tokenizeMaxLength ?? DEFAULT_TOKENIZE_MAX_LENGTH;
    }
    private processDiffResult(fileDiff: FileDiffMetadata, renderRange: RenderRange, { code, themeStyles, baseThemeType }: ThemedDiffResult): HunksRenderResult {
        const { diffStyle, disableFileHeader, expandUnchanged, expansionLineCount, collapsedContextThreshold, hunkSeparators, } = this.getOptionsWithDefaults();
        const isRenderCacheDirty = this.renderCache?.isDirty ?? false;
        const unified = diffStyle === 'unified';
        const canHydrateContext = canHydrateCollapsedContext(fileDiff, this.options.loadDiffFiles != null);
        const isExpandableDiff = !fileDiff.isPartial || canHydrateContext;
        let additionsContentAST: ElementContent[] | undefined = [];
        let deletionsContentAST: ElementContent[] | undefined = [];
        let unifiedContentAST: ElementContent[] | undefined = [];
        const hunkData: HunkData[] = [];
        const { additionLines, deletionLines } = code;
        const context: ProcessContext = {
            rowCount: 0,
            hunkSeparators,
            additionsContentAST,
            deletionsContentAST,
            unifiedContentAST,
            unifiedGutterAST: createGutterWrapper(),
            deletionsGutterAST: createGutterWrapper(),
            additionsGutterAST: createGutterWrapper(),
            expansionLineCount,
            hunkData,
            incrementRowCount(count = 1) {
                context.rowCount += count;
            },
            pushToGutter(type: CodeColumnType, element: HASTElement) {
                switch (type) {
                    case 'unified': {
                        context.unifiedGutterAST.children.push(element);
                        break;
                    }
                    case 'deletions': {
                        context.deletionsGutterAST.children.push(element);
                        break;
                    }
                    case 'additions': {
                        context.additionsGutterAST.children.push(element);
                        break;
                    }
                }
            },
        };
        const trailingRangeSize = getTrailingContextRangeSize({
            fileDiff,
            errorPrefix: 'DiffHunksRenderer.processDiffResult',
        });
        const pendingSplitContext: PendingSplitContext = {
            size: 0,
            side: undefined,
            increment() {
                this.size += 1;
            },
            flush() {
                if (diffStyle === 'unified') {
                    return;
                }
                if (this.size <= 0 || this.side == null) {
                    this.side = undefined;
                    this.size = 0;
                    return;
                }
                if (this.side === 'additions') {
                    context.pushToGutter('additions', createGutterGap(undefined, 'buffer', this.size));
                    additionsContentAST?.push(createEmptyRowBuffer(this.size));
                }
                else {
                    context.pushToGutter('deletions', createGutterGap(undefined, 'buffer', this.size));
                    deletionsContentAST?.push(createEmptyRowBuffer(this.size));
                }
                this.size = 0;
                this.side = undefined;
            },
        };
        const pushGutterLineNumber = (type: CodeColumnType, lineType: LineTypes | 'buffer' | 'separator' | 'annotation', lineNumber: number, lineIndex: string, gutterProperties: Properties | undefined) => {
            context.pushToGutter(type, createGutterItem(lineType, lineNumber, lineIndex, gutterProperties));
        };
        function pushSeparators(props: PushSeparatorProps) {
            pendingSplitContext.flush();
            if (diffStyle === 'unified') {
                pushSeparator('unified', props, context);
            }
            else {
                pushSeparator('deletions', props, context);
                pushSeparator('additions', props, context);
            }
        }
        this.pushFileLevelAnnotations(fileDiff, diffStyle, renderRange, context);
        iterateOverDiff({
            diff: fileDiff,
            diffStyle,
            startingLine: renderRange.startingLine,
            totalLines: renderRange.totalLines,
            expandedHunks: expandUnchanged ? true : this.expandedHunks,
            collapsedContextThreshold,
            callback: ({ hunkIndex, hunk, collapsedBefore, collapsedAfter, additionLine, deletionLine, type, }) => {
                const splitLineIndex = deletionLine != null
                    ? deletionLine.splitLineIndex
                    : additionLine.splitLineIndex;
                const unifiedLineIndex = additionLine != null
                    ? additionLine.unifiedLineIndex
                    : deletionLine.unifiedLineIndex;
                if (diffStyle === 'split' && type !== 'change') {
                    pendingSplitContext.flush();
                }
                if (collapsedBefore > 0) {
                    pushSeparators({
                        hunkIndex,
                        collapsedLines: collapsedBefore,
                        rangeSize: Math.max(hunk?.collapsedBefore ?? 0, 0),
                        hunkSpecs: hunk?.hunkSpecs,
                        isFirstHunk: hunkIndex === 0,
                        isLastHunk: false,
                        isExpandable: isExpandableDiff,
                    });
                }
                const lineIndex = diffStyle === 'unified' ? unifiedLineIndex : splitLineIndex;
                const renderedLineContext: RenderedLineContext = {
                    type,
                    hunkIndex,
                    lineIndex,
                    unifiedLineIndex,
                    splitLineIndex,
                    deletionLine,
                    additionLine,
                };
                if (diffStyle === 'unified') {
                    const injectedRows = this.getUnifiedInjectedRowsForLine?.(renderedLineContext);
                    if (injectedRows?.before != null) {
                        pushUnifiedInjectedRows(injectedRows.before, context);
                    }
                    let deletionLineContent = deletionLine != null
                        ? deletionLines[deletionLine.lineIndex]
                        : undefined;
                    let additionLineContent = additionLine != null
                        ? additionLines[additionLine.lineIndex]
                        : undefined;
                    if (deletionLineContent == null && additionLineContent == null) {
                        const errorMessage = 'DiffHunksRenderer.processDiffResult: deletionLine and additionLine are null, something is wrong';
                        console.error(errorMessage, { file: fileDiff.name });
                        throw new Error(errorMessage);
                    }
                    const lineType = type === 'change'
                        ? additionLine != null
                            ? 'change-addition'
                            : 'change-deletion'
                        : type;
                    const lineDecoration = this.getUnifiedLineDecoration({
                        // NOTE: This function gets extended so don't remove
                        // these extra props
                        type,
                        lineType,
                        additionLineIndex: additionLine?.lineIndex,
                        deletionLineIndex: deletionLine?.lineIndex,
                    });
                    pushGutterLineNumber('unified', lineDecoration.gutterLineType, additionLine != null
                        ? additionLine.lineNumber
                        : deletionLine.lineNumber, `${unifiedLineIndex},${splitLineIndex}`, lineDecoration.gutterProperties);
                    if (additionLineContent != null) {
                        additionLineContent = withContentProperties(additionLineContent, lineDecoration.contentProperties, isRenderCacheDirty && additionLine != null
                            ? {
                                'data-line': additionLine.lineNumber,
                                'data-line-index': `${unifiedLineIndex},${splitLineIndex}`,
                            }
                            : undefined);
                    }
                    else if (deletionLineContent != null) {
                        deletionLineContent = withContentProperties(deletionLineContent, lineDecoration.contentProperties, isRenderCacheDirty && deletionLine != null
                            ? {
                                'data-line': deletionLine.lineNumber,
                                'data-line-index': `${unifiedLineIndex},${splitLineIndex}`,
                            }
                            : undefined);
                    }
                    pushLineWithAnnotation({
                        diffStyle: 'unified',
                        type: type,
                        deletionLine: deletionLineContent,
                        additionLine: additionLineContent,
                        unifiedSpan: this.getAnnotations('unified', deletionLine?.lineNumber, additionLine?.lineNumber, hunkIndex, lineIndex),
                        createAnnotationElement: (span) => this.createAnnotationElement(span),
                        context,
                    });
                    if (injectedRows?.after != null) {
                        pushUnifiedInjectedRows(injectedRows.after, context);
                    }
                }
                else {
                    const injectedRows = this.getSplitInjectedRowsForLine?.(renderedLineContext);
                    if (injectedRows?.before != null) {
                        pushSplitInjectedRows(injectedRows.before, context, pendingSplitContext);
                    }
                    let deletionLineContent = deletionLine != null
                        ? deletionLines[deletionLine.lineIndex]
                        : undefined;
                    let additionLineContent = additionLine != null
                        ? additionLines[additionLine.lineIndex]
                        : undefined;
                    const deletionLineDecoration = this.getSplitLineDecoration({
                        side: 'deletions',
                        type,
                        lineIndex: deletionLine?.lineIndex,
                    });
                    const additionLineDecoration = this.getSplitLineDecoration({
                        side: 'additions',
                        type,
                        lineIndex: additionLine?.lineIndex,
                    });
                    if (deletionLineContent == null && additionLineContent == null) {
                        const errorMessage = 'DiffHunksRenderer.processDiffResult: deletionLine and additionLine are null, something is wrong';
                        console.error(errorMessage, { file: fileDiff.name });
                        throw new Error(errorMessage);
                    }
                    const missingSide = (() => {
                        if (type === 'change') {
                            if (additionLineContent == null) {
                                return 'additions';
                            }
                            else if (deletionLineContent == null) {
                                return 'deletions';
                            }
                        }
                        return undefined;
                    })();
                    if (missingSide != null) {
                        if (pendingSplitContext.side != null &&
                            pendingSplitContext.side !== missingSide) {
                            pendingSplitContext.flush();
                        }
                        pendingSplitContext.side = missingSide;
                        pendingSplitContext.increment();
                    }
                    else if (type === 'change') {
                        // A change row with both sides fills the column a pending
                        // one-sided buffer was holding open (an insert/delete block
                        // directly followed by a paired block, from similarity
                        // realignment); flush first so the buffer lands above this row.
                        pendingSplitContext.flush();
                    }
                    const annotationSpans = this.getAnnotations('split', deletionLine?.lineNumber, additionLine?.lineNumber, hunkIndex, lineIndex);
                    if (annotationSpans != null && pendingSplitContext.size > 0) {
                        pendingSplitContext.flush();
                    }
                    if (deletionLine != null) {
                        const deletionLineDecorated = withContentProperties(deletionLineContent, deletionLineDecoration.contentProperties, isRenderCacheDirty
                            ? {
                                'data-line': deletionLine.lineNumber,
                                'data-line-index': `${deletionLine.unifiedLineIndex},${splitLineIndex}`,
                            }
                            : undefined);
                        pushGutterLineNumber('deletions', deletionLineDecoration.gutterLineType, deletionLine.lineNumber, `${deletionLine.unifiedLineIndex},${splitLineIndex}`, deletionLineDecoration.gutterProperties);
                        if (deletionLineDecorated != null) {
                            deletionLineContent = deletionLineDecorated;
                        }
                    }
                    if (additionLine != null) {
                        const additionLineDecorated = withContentProperties(additionLineContent, additionLineDecoration.contentProperties, isRenderCacheDirty
                            ? {
                                'data-line': additionLine.lineNumber,
                                'data-line-index': `${additionLine.unifiedLineIndex},${splitLineIndex}`,
                            }
                            : undefined);
                        pushGutterLineNumber('additions', additionLineDecoration.gutterLineType, additionLine.lineNumber, `${additionLine.unifiedLineIndex},${splitLineIndex}`, additionLineDecoration.gutterProperties);
                        if (additionLineDecorated != null) {
                            additionLineContent = additionLineDecorated;
                        }
                    }
                    pushLineWithAnnotation({
                        diffStyle: 'split',
                        type: type,
                        additionLine: additionLineContent,
                        deletionLine: deletionLineContent,
                        ...annotationSpans,
                        createAnnotationElement: (span) => this.createAnnotationElement(span),
                        context,
                    });
                    if (injectedRows?.after != null) {
                        pushSplitInjectedRows(injectedRows.after, context, pendingSplitContext);
                    }
                }
                const isFinalSplitHunkRow = diffStyle === 'split' &&
                    hunk != null &&
                    splitLineIndex === hunk.splitLineStart + hunk.splitLineCount - 1;
                const isFinalHunkRow = hunkIndex === fileDiff.hunks.length - 1 &&
                    hunk != null &&
                    (diffStyle === 'split'
                        ? splitLineIndex === hunk.splitLineStart + hunk.splitLineCount - 1
                        : unifiedLineIndex ===
                            hunk.unifiedLineStart + hunk.unifiedLineCount - 1);
                const splitNoEOFCRDeletion = isFinalSplitHunkRow
                    ? hunk.noEOFCRDeletions
                    : false;
                const splitNoEOFCRAddition = isFinalSplitHunkRow
                    ? hunk.noEOFCRAdditions
                    : false;
                const noEOFCRDeletion = (deletionLine?.noEOFCR ?? false) || splitNoEOFCRDeletion;
                const noEOFCRAddition = (additionLine?.noEOFCR ?? false) || splitNoEOFCRAddition;
                if (noEOFCRAddition || noEOFCRDeletion) {
                    if (diffStyle === 'split') {
                        pendingSplitContext.flush();
                    }
                    if (noEOFCRDeletion) {
                        const noEOFType = type === 'context' || type === 'context-expanded'
                            ? type
                            : 'change-deletion';
                        if (diffStyle === 'unified') {
                            context.unifiedContentAST.push(createNoNewlineElement(noEOFType));
                            context.pushToGutter('unified', createGutterGap(noEOFType, 'metadata', 1));
                        }
                        else {
                            context.deletionsContentAST.push(createNoNewlineElement(noEOFType));
                            context.pushToGutter('deletions', createGutterGap(noEOFType, 'metadata', 1));
                            if (!noEOFCRAddition) {
                                context.pushToGutter('additions', createGutterGap(undefined, 'buffer', 1));
                                context.additionsContentAST.push(createEmptyRowBuffer(1));
                            }
                        }
                    }
                    if (noEOFCRAddition) {
                        const noEOFType = type === 'context' || type === 'context-expanded'
                            ? type
                            : 'change-addition';
                        if (diffStyle === 'unified') {
                            context.unifiedContentAST.push(createNoNewlineElement(noEOFType));
                            context.pushToGutter('unified', createGutterGap(noEOFType, 'metadata', 1));
                        }
                        else {
                            context.additionsContentAST.push(createNoNewlineElement(noEOFType));
                            context.pushToGutter('additions', createGutterGap(noEOFType, 'metadata', 1));
                            if (!noEOFCRDeletion) {
                                context.pushToGutter('deletions', createGutterGap(undefined, 'buffer', 1));
                                context.deletionsContentAST.push(createEmptyRowBuffer(1));
                            }
                        }
                    }
                    context.incrementRowCount(1);
                }
                if (hunkSeparators !== 'simple' &&
                    hunkSeparators !== 'metadata' &&
                    (collapsedAfter > 0 || (isFinalHunkRow && canHydrateContext))) {
                    pushSeparators({
                        hunkIndex: type === 'context-expanded' ? hunkIndex : hunkIndex + 1,
                        collapsedLines: isFinalHunkRow && canHydrateContext ? 'unknown' : collapsedAfter,
                        rangeSize: trailingRangeSize,
                        hunkSpecs: undefined,
                        isFirstHunk: false,
                        isLastHunk: true,
                        isExpandable: isExpandableDiff,
                    });
                }
                context.incrementRowCount(1);
            },
        });
        if (diffStyle === 'split') {
            pendingSplitContext.flush();
        }
        const totalLines = Math.max(getTotalLineCountFromHunks(fileDiff.hunks), fileDiff.additionLines.length ?? 0, fileDiff.deletionLines.length ?? 0);
        const hasBuffer = renderRange.bufferBefore > 0 || renderRange.bufferAfter > 0;
        // Determine which ASTs to include based on diff style and file type
        const shouldIncludeAdditions = !unified && fileDiff.type !== 'deleted';
        const shouldIncludeDeletions = !unified && fileDiff.type !== 'new';
        const hasContent = context.rowCount > 0 || hasBuffer;
        additionsContentAST =
            shouldIncludeAdditions && hasContent ? additionsContentAST : undefined;
        deletionsContentAST =
            shouldIncludeDeletions && hasContent ? deletionsContentAST : undefined;
        unifiedContentAST = unified && hasContent ? unifiedContentAST : undefined;
        const preNode = this.createPreElement(deletionsContentAST != null && additionsContentAST != null, totalLines);
        return {
            fileDiff,
            unifiedGutterAST: unified && hasContent ? context.unifiedGutterAST.children : undefined,
            unifiedContentAST,
            deletionsGutterAST: shouldIncludeDeletions && hasContent
                ? context.deletionsGutterAST.children
                : undefined,
            deletionsContentAST,
            additionsGutterAST: shouldIncludeAdditions && hasContent
                ? context.additionsGutterAST.children
                : undefined,
            additionsContentAST,
            hunkData,
            preNode,
            themeStyles,
            baseThemeType,
            headerElement: !disableFileHeader
                ? this.renderHeader(fileDiff)
                : undefined,
            totalLines,
            rowCount: context.rowCount,
            bufferBefore: renderRange.bufferBefore,
            bufferAfter: renderRange.bufferAfter,
            // FIXME
            css: '',
        };
    }
    public renderCodeAST(type: 'unified' | 'deletions' | 'additions', result: HunksRenderResult): ElementContent[] | undefined {
        const gutterAST = type === 'unified'
            ? result.unifiedGutterAST
            : type === 'deletions'
                ? result.deletionsGutterAST
                : result.additionsGutterAST;
        const contentAST = type === 'unified'
            ? result.unifiedContentAST
            : type === 'deletions'
                ? result.deletionsContentAST
                : result.additionsContentAST;
        if (gutterAST == null || contentAST == null) {
            return undefined;
        }
        const gutter = createGutterWrapper(gutterAST);
        gutter.properties.style = `grid-row: span ${result.rowCount}`;
        const contentColumn = createContentColumn(contentAST, result.rowCount);
        return [gutter, contentColumn];
    }
    public renderFullAST(result: HunksRenderResult, children: ElementContent[] = []): HASTElement {
        const containerSize = this.getOptionsWithDefaults().hunkSeparators === 'line-info';
        const unifiedAST = this.renderCodeAST('unified', result);
        if (unifiedAST != null) {
            children.push(createHastElement({
                tagName: 'code',
                children: unifiedAST,
                properties: {
                    'data-code': '',
                    'data-container-size': containerSize ? '' : undefined,
                    'data-unified': '',
                },
            }));
            return { ...result.preNode, children };
        }
        const deletionsAST = this.renderCodeAST('deletions', result);
        if (deletionsAST != null) {
            children.push(createHastElement({
                tagName: 'code',
                children: deletionsAST,
                properties: {
                    'data-code': '',
                    'data-container-size': containerSize ? '' : undefined,
                    'data-deletions': '',
                },
            }));
        }
        const additionsAST = this.renderCodeAST('additions', result);
        if (additionsAST != null) {
            children.push(createHastElement({
                tagName: 'code',
                children: additionsAST,
                properties: {
                    'data-code': '',
                    'data-container-size': containerSize ? '' : undefined,
                    'data-additions': '',
                },
            }));
        }
        return { ...result.preNode, children };
    }
    public renderFullHTML(result: HunksRenderResult, tempChildren: ElementContent[] = []): string {
        return toHtml(this.renderFullAST(result, tempChildren));
    }
    public renderPartialHTML(children: ElementContent[], columnType?: 'unified' | 'deletions' | 'additions'): string {
        if (columnType == null) {
            return toHtml(children);
        }
        return toHtml(createHastElement({
            tagName: 'code',
            children,
            properties: {
                'data-code': '',
                'data-container-size': this.getOptionsWithDefaults().hunkSeparators === 'line-info'
                    ? ''
                    : undefined,
                [`data-${columnType}`]: '',
            },
        }));
    }
    private pushFileLevelAnnotations(fileDiff: FileDiffMetadata, diffStyle: 'unified' | 'split', renderRange: RenderRange, context: ProcessContext): void {
        if (!shouldRenderFileAnnotations(renderRange)) {
            return;
        }
        const deletionAnnotationNames = fileDiff.type !== 'new'
            ? this.getAnnotationNames(getFileAnnotations(this.deletionAnnotations))
            : [];
        const additionAnnotationNames = fileDiff.type !== 'deleted'
            ? this.getAnnotationNames(getFileAnnotations(this.additionAnnotations))
            : [];
        if (deletionAnnotationNames.length === 0 &&
            additionAnnotationNames.length === 0) {
            return;
        }
        const hunkIndex = FILE_ANNOTATION_HUNK_INDEX;
        const lineIndex = FILE_ANNOTATION_LINE_INDEX;
        const { createAnnotationElement } = this;
        if (diffStyle === 'unified') {
            pushLineWithAnnotation({
                diffStyle,
                type: 'context',
                unifiedSpan: {
                    type: 'annotation',
                    hunkIndex,
                    lineIndex,
                    annotations: deletionAnnotationNames.concat(additionAnnotationNames),
                },
                createAnnotationElement,
                context,
            });
            return;
        }
        pushLineWithAnnotation({
            diffStyle,
            type: 'context',
            deletionSpan: {
                type: 'annotation',
                hunkIndex,
                lineIndex,
                annotations: deletionAnnotationNames,
