export * from './tokenizer';
export * from './types';

import type { ThemedToken } from 'shiki/core';
import { ShikiStreamTokenizer } from './tokenizer';
import type { CodeToTokenTransformStreamOptions, RecallToken } from './types';
/**
 * Create a transform stream that takes code chunks and emits themed tokens.
 */
export class CodeToTokenTransformStream extends TransformStream<string, ThemedToken | RecallToken> {
    readonly tokenizer: ShikiStreamTokenizer;
    readonly options: CodeToTokenTransformStreamOptions;
    constructor(options: CodeToTokenTransformStreamOptions) {
        const tokenizer = new ShikiStreamTokenizer(options);
        const { allowRecalls = false } = options;
        super({
            async transform(chunk, controller) {
                const { stable, unstable: buffer, recall, } = await tokenizer.enqueue(chunk);
                if (allowRecalls && recall > 0) {
                    controller.enqueue({ recall });
                }
                for (const token of stable) {
                    controller.enqueue(token);
                }
                if (allowRecalls) {
                    for (const token of buffer) {
                        controller.enqueue(token);
                    }
                }
            },
            // oxlint-disable-next-line typescript/require-await
            async flush(controller) {
                const { stable } = tokenizer.close();
                // if allow recalls, the tokens should already be sent
                if (!allowRecalls) {
                    for (const token of stable) {
                        controller.enqueue(token);
                    }
                }
            },
        });
        this.tokenizer = tokenizer;
        this.options = options;
    }
}

import type { GrammarState, ThemedToken } from 'shiki/core';
import { appendItems } from '../utils/appendItems';
import type { ShikiStreamTokenizerEnqueueResult, ShikiStreamTokenizerOptions, } from './types';
export class ShikiStreamTokenizer {
    public readonly options: ShikiStreamTokenizerOptions;
    public tokensStable: ThemedToken[] = [];
    public tokensUnstable: ThemedToken[] = [];
    public lastUnstableCodeChunk: string = '';
    public lastStableGrammarState: GrammarState | undefined;
    constructor(options: ShikiStreamTokenizerOptions) {
        this.options = options;
    }
    /**
     * Enqueue a chunk of code to the buffer.
     */
    // oxlint-disable-next-line typescript/require-await
    async enqueue(chunk: string): Promise<ShikiStreamTokenizerEnqueueResult> {
        const chunkLines = (this.lastUnstableCodeChunk + chunk).split('\n');
        const stable: ThemedToken[] = [];
        let unstable: ThemedToken[] = [];
        const recall = this.tokensUnstable.length;
        chunkLines.forEach((line, i) => {
            const isLastLine = i === chunkLines.length - 1;
            const result = this.options.highlighter.codeToTokens(line, {
                ...this.options,
                grammarState: this.lastStableGrammarState,
            });
            const tokens = result.tokens[0]; // only one line
            if (!isLastLine)
                tokens.push({ content: '\n', offset: 0 });
            if (!isLastLine) {
                this.lastStableGrammarState = result.grammarState;
                stable.push(...tokens);
            }
            else {
                unstable = tokens;
                this.lastUnstableCodeChunk = line;
            }
        });
        appendItems(this.tokensStable, stable);
        this.tokensUnstable = unstable;
        return {
            recall,
            stable,
            unstable,
        };
    }
    close(): {
        stable: ThemedToken[];
    } {
        const stable = this.tokensUnstable;
        this.tokensUnstable = [];
        this.lastUnstableCodeChunk = '';
        this.lastStableGrammarState = undefined;
        return {
            stable,
        };
    }
    clear(): void {
        this.tokensStable = [];
        this.tokensUnstable = [];
        this.lastUnstableCodeChunk = '';
        this.lastStableGrammarState = undefined;
    }
    clone(): ShikiStreamTokenizer {
        const clone = new ShikiStreamTokenizer(this.options);
        clone.lastUnstableCodeChunk = this.lastUnstableCodeChunk;
        clone.tokensUnstable = this.tokensUnstable;
        clone.tokensStable = this.tokensStable;
        clone.lastStableGrammarState = this.lastStableGrammarState;
        return clone;
    }
}

import type { CodeToTokensOptions, HighlighterCore, HighlighterGeneric, ThemedToken, } from 'shiki/core';
