}
export async function preloadFile<LAnnotation = undefined, Caret = undefined>({ file, options, annotations, }: PreloadFileOptions<LAnnotation, Caret>): Promise<PreloadedFileResult<LAnnotation, Caret>> {
    const fileRenderer = new FileRenderer<LAnnotation>({
        ...options,
        // Match the client's option snapshot: token callbacks imply the
        // transformer, so server markup hydrates into identical client renders.
        useTokenTransformer: shouldUseTokenTransformer(options),
        headerRenderMode: options?.renderCustomHeader != null ? 'custom' : 'default',
    });
    // Set line annotations if provided
    if (annotations !== undefined && annotations.length > 0) {
        fileRenderer.setLineAnnotations(annotations);
    }
    const fileResult = await fileRenderer.asyncRender(file);
    const children = [createStyleElement(fileResult.css, true)];
    children.push(createThemeStyleElement(wrapThemeCSS(fileResult.themeStyles, fileResult.baseThemeType ?? options?.themeType ?? 'system')));
    if (options?.unsafeCSS != null) {
        children.push(createStyleElement(options.unsafeCSS));
    }
    if (fileResult.headerAST != null) {
        children.push(fileResult.headerAST);
    }
    const code = fileRenderer.renderFullAST(fileResult);
    code.properties['data-dehydrated'] = '';
    children.push(code);
    return {
        file,
        options,
        annotations,
        prerenderedHTML: renderHTML(children),
    };
}

import type { FileDiffOptions } from '../components/FileDiff';
import { parsePatchFiles } from '../utils/parsePatchFiles';
import { preloadFileDiff, type PreloadFileDiffResult } from './preloadDiffs';
export type PreloadPatchFileOptions<LAnnotation, Caret> = {
    patch: string;
    options?: FileDiffOptions<LAnnotation, Caret>;
};
export async function preloadPatchFile<LAnnotation = undefined, Caret = undefined>({ patch, options, }: PreloadPatchFileOptions<LAnnotation, Caret>): Promise<PreloadFileDiffResult<LAnnotation, Caret>[]> {
    const diffs: Promise<PreloadFileDiffResult<LAnnotation, Caret>>[] = [];
    const patches = parsePatchFiles(patch);
    for (const patch of patches) {
        for (const fileDiff of patch.files) {
            diffs.push(preloadFileDiff<LAnnotation, Caret>({ fileDiff, options }));
        }
    }
    return await Promise.all(diffs);
}

