import { toHtml } from 'hast-util-to-html';
import { SVGSpriteSheet } from '../sprite';
export function renderHTML(children: HASTElement[]) {
    return `${SVGSpriteSheet}${toHtml(children)}`;
}

declare module '*.css' {
    const file: string;
    export default file;
}
declare module '*.css?inline' {
    const file: string;
    export default file;
}

@layer base, theme, rendered, unsafe;

@layer base {
  :host {
    --diffs-font-fallback:
      'SF Mono', Monaco, Consolas, 'Ubuntu Mono', 'Liberation Mono',
      'Courier New', monospace;
    --diffs-header-font-fallback:
      system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue',
      'Noto Sans', 'Liberation Sans', Arial, sans-serif;

    --diffs-mixer: light-dark(black, white);
    --diffs-gap-fallback: 8px;
    --diffs-scrollbar-gutter-fallback: 6px;
    --diffs-scrollbar-gutter: var(
      --diffs-scrollbar-gutter-override,
      var(
        --diffs-scrollbar-gutter-measured,
        var(--diffs-scrollbar-gutter-fallback)
      )
    );

    --diffs-added-light: #0dbe4e;
    --diffs-added-dark: #5ecc71;
    --diffs-modified-light: #009fff;
    --diffs-modified-dark: #69b1ff;
    --diffs-deleted-light: #ff2e3f;
    --diffs-deleted-dark: #ff6762;
    --diffs-warning-light: #d5a910;
    --diffs-warning-dark: #ffd452;

    /*
    // Available CSS Color Overrides
    --diffs-bg-buffer-override
    --diffs-bg-hover-override
    --diffs-bg-context-override
    --diffs-bg-context-gutter-override
    --diffs-bg-separator-override
    --diffs-bg-caret-override

    --diffs-fg-number-override
    --diffs-fg-number-addition-override
    --diffs-fg-number-deletion-override
    --diffs-fg-conflict-marker-override

    --diffs-deletion-color-override
    --diffs-addition-color-override
    --diffs-modified-color-override

    --diffs-bg-deletion-override
    --diffs-bg-deletion-number-override
    --diffs-bg-deletion-emphasis-override

    --diffs-bg-addition-override
    --diffs-bg-addition-number-override
    --diffs-bg-addition-emphasis-override

    --conflict-bg-current-override
    --conflict-bg-current-number-override
    --conflict-bg-current-header-override
    --conflict-bg-incoming-override
    --conflict-bg-incoming-number-override
    --conflict-bg-incoming-header-override

    // Line Selection Color Overrides (for enableLineSelection)
    --diffs-selection-color-override
    --diffs-bg-selection-override
    --diffs-bg-selection-number-override

    // Available CSS Layout Overrides
    --diffs-gap-inline
    --diffs-gap-block
    --diffs-gap-style
    --diffs-scrollbar-gutter-override
    --diffs-tab-size
    --diffs-popover-gap (edit mode: inset for edge-clamped popovers)
    */

    color-scheme: light dark;
    display: block;
    font-family: var(
      --diffs-header-font-family,
      var(--diffs-header-font-fallback)
    );
    font-size: var(--diffs-font-size, 13px);
    line-height: var(--diffs-line-height, 20px);
    font-feature-settings: var(--diffs-font-features);

    /* NOTE(amadeus): we cannot use 'in oklch' because current versions of cursor
     * and vscode use an older build of chrome that appears to have a bug with
     * color-mix and 'in oklch', so use 'in lab' instead */
    --diffs-bg: light-dark(
      var(--diffs-light-bg, #fff),
      var(--diffs-dark-bg, #000)
    );
    --diffs-bg-buffer: var(
      --diffs-bg-buffer-override,
      light-dark(
        color-mix(in lab, var(--diffs-bg) 92%, var(--diffs-mixer)),
        color-mix(in lab, var(--diffs-bg) 92%, var(--diffs-mixer))
      )
    );
    --diffs-bg-context: var(
      --diffs-bg-context-override,
      light-dark(
        color-mix(in lab, var(--diffs-bg) 98.5%, var(--diffs-mixer)),
        color-mix(in lab, var(--diffs-bg) 92.5%, var(--diffs-mixer))
      )
    );
    --diffs-bg-context-gutter: var(
      --diffs-bg-context-gutter-override,
      light-dark(
        color-mix(in lab, var(--diffs-bg-context) 90%, var(--diffs-bg)),
        color-mix(in lab, var(--diffs-bg-context) 45%, var(--diffs-bg))
      )
    );
    --diffs-bg-separator: var(
      --diffs-bg-separator-override,
      light-dark(
        color-mix(in lab, var(--diffs-bg) 96%, var(--diffs-mixer)),
        color-mix(in lab, var(--diffs-bg) 85%, var(--diffs-mixer))
      )
    );

    --diffs-fg: light-dark(var(--diffs-light, #000), var(--diffs-dark, #fff));
    --diffs-fg-number: var(
      --diffs-fg-number-override,
      light-dark(
        color-mix(in lab, var(--diffs-fg) 65%, var(--diffs-bg)),
        color-mix(in lab, var(--diffs-fg) 65%, var(--diffs-bg))
      )
    );
    --diffs-fg-conflict-marker: var(
      --diffs-fg-conflict-marker-override,
      var(--diffs-fg-number)
    );

    --diffs-deletion-base: var(
      --diffs-deletion-color-override,
      light-dark(
        var(
          --diffs-light-deletion-color,
          var(--diffs-deletion-color, var(--diffs-deleted-light))
        ),
        var(
          --diffs-dark-deletion-color,
          var(--diffs-deletion-color, var(--diffs-deleted-dark))
        )
      )
    );
    --diffs-addition-base: var(
      --diffs-addition-color-override,
      light-dark(
        var(
          --diffs-light-addition-color,
          var(--diffs-addition-color, var(--diffs-added-light))
        ),
        var(
          --diffs-dark-addition-color,
          var(--diffs-addition-color, var(--diffs-added-dark))
        )
      )
    );
    --diffs-modified-base: var(
      --diffs-modified-color-override,
      light-dark(
        var(
          --diffs-light-modified-color,
          var(--diffs-modified-color, var(--diffs-modified-light))
        ),
        var(
          --diffs-dark-modified-color,
          var(--diffs-modified-color, var(--diffs-modified-dark))
        )
      )
    );

    /* NOTE(amadeus): we cannot use 'in oklch' because current versions of cursor
   * and vscode use an older build of chrome that appears to have a bug with
   * color-mix and 'in oklch', so use 'in lab' instead */
    --diffs-bg-deletion: var(
      --diffs-bg-deletion-override,
      light-dark(
        color-mix(in lab, var(--diffs-bg) 88%, var(--diffs-deletion-base)),
        color-mix(in lab, var(--diffs-bg) 80%, var(--diffs-deletion-base))
      )
    );
    --diffs-bg-deletion-emphasis: var(
      --diffs-bg-deletion-emphasis-override,
      light-dark(
        rgb(from var(--diffs-deletion-base) r g b / 0.15),
        rgb(from var(--diffs-deletion-base) r g b / 0.2)
      )
    );

    --diffs-bg-addition: var(
      --diffs-bg-addition-override,
      light-dark(
        color-mix(in lab, var(--diffs-bg) 88%, var(--diffs-addition-base)),
        color-mix(in lab, var(--diffs-bg) 80%, var(--diffs-addition-base))
      )
    );
    --diffs-bg-addition-emphasis: var(
      --diffs-bg-addition-emphasis-override,
      light-dark(
        rgb(from var(--diffs-addition-base) r g b / 0.15),
        rgb(from var(--diffs-addition-base) r g b / 0.2)
      )
    );

    --diffs-selection-base: var(--diffs-modified-base);
    --diffs-selection-number-fg: light-dark(
      color-mix(in lab, var(--diffs-selection-base) 65%, var(--diffs-mixer)),
      color-mix(in lab, var(--diffs-selection-base) 75%, var(--diffs-mixer))
    );
    background-color: var(--diffs-bg);
    color: var(--diffs-fg);
  }

  /* NOTE(mdo): Some semantic HTML elements (e.g. `pre`, `code`) have default
 * user-agent styles. These must be overridden to use our custom styles. */
  pre,
  code,
  [data-error-wrapper] {
    isolation: isolate;
    margin: 0;
    padding: 0;
    display: block;
    outline: none;
    font-family: var(--diffs-font-family, var(--diffs-font-fallback));
  }

  pre,
  code {
    background-color: var(--diffs-bg);
  }

  code {
    contain: content;
  }

  input,
  button {
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
  }

  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  [data-icon-sprite] {
    display: none;
  }

  /* NOTE(mdo): Headers and separators are within pre/code, so we need to reset
   * their font-family explicitly. */
  [data-diffs-header],
  [data-separator] {
    font-family: var(
      --diffs-header-font-family,
      var(--diffs-header-font-fallback)
    );
  }

  [data-diffs-header][data-sticky] {
    position: sticky;
    top: 0;
    z-index: 1;
    background-color: var(--diffs-bg);
  }

  [data-file-info] {
    padding: 10px;
    font-weight: 700;
    color: var(--fg);
    /* NOTE(amadeus): we cannot use 'in oklch' because current versions of cursor
   * and vscode use an older build of chrome that appears to have a bug with
   * color-mix and 'in oklch', so use 'in lab' instead */
    background-color: color-mix(in lab, var(--bg) 98%, var(--fg));
    border-block: 1px solid color-mix(in lab, var(--bg) 95%, var(--fg));
  }

  [data-diff],
  [data-file] {
    /* This feels a bit crazy to me... so I need to think about it a bit more... */
    --diffs-grid-number-column-width: minmax(min-content, max-content);
    --diffs-code-grid: var(--diffs-grid-number-column-width) 1fr;

    &[data-dehydrated] {
      --diffs-code-grid: var(--diffs-grid-number-column-width) minmax(0, 1fr);
    }

    &:hover [data-code]::-webkit-scrollbar-thumb {
      background-color: var(--diffs-bg-context);
    }
  }

  /* iOS WebKit uses overlay scrollbars, so unmeasured layout compensation
   * should start at zero rather than the desktop custom-scrollbar fallback. */
  @supports (-webkit-touch-callout: none) {
    :host {
      --diffs-scrollbar-gutter-fallback: 0px;
    }
  }

  [data-line] span,
  [data-edit-prediction-suffix] span {
    color: light-dark(
      var(--diffs-token-light, var(--diffs-light, var(--diffs-fg))),
      var(--diffs-token-dark, var(--diffs-dark, var(--diffs-fg)))
    );
    background-color: light-dark(
      var(--diffs-token-light-bg, inherit),
      var(--diffs-token-dark-bg, inherit)
    );
    font-weight: light-dark(
      var(--diffs-token-light-font-weight, inherit),
      var(--diffs-token-dark-font-weight, inherit)
    );
    font-style: light-dark(
      var(--diffs-token-light-font-style, inherit),
      var(--diffs-token-dark-font-style, inherit)
    );
    text-decoration: light-dark(
      var(--diffs-token-light-text-decoration, inherit),
      var(--diffs-token-dark-text-decoration, inherit)
    );
  }

  /* Line Color and BG Calculations */
  [data-line],
  [data-gutter-buffer],
  [data-column-number],
  [data-line-annotation],
  [data-no-newline],
  [data-merge-conflict],
  [data-merge-conflict-actions],
  [data-editor-overlay] {
    /* Pre-fill css variables for appropriate up-mixing */
    --diffs-computed-decoration-bg: var(--diffs-bg);
    --diffs-computed-diff-line-bg: var(--diffs-computed-decoration-bg);
    --diffs-computed-selected-line-bg: var(--diffs-computed-diff-line-bg);
    --diffs-computed-editor-active-line-bg: var(
      --diffs-computed-selected-line-bg
    );
    --diffs-computed-hovered-line-bg: var(
      --diffs-computed-editor-active-line-bg
    );

    --diffs-hover-mix-target: var(
      --diffs-bg-hover-override,
      var(--diffs-mixer)
    );
    --diffs-line-bg: var(--diffs-computed-hovered-line-bg);

    color: var(--diffs-fg);
    background-color: var(--diffs-line-bg, var(--diffs-bg));
  }

  [data-line],
  [data-no-newline] {
    &[data-decoration-bg] {
      --mix-deco-light: 92%;
      --mix-deco-dark: 85%;

      &[data-decoration-bg-depth='2'] {
        --mix-deco-light: 88%;
        --mix-deco-dark: 80%;
      }

      &[data-decoration-bg-depth='3'] {
        --mix-deco-light: 85%;
        --mix-deco-dark: 78%;
      }

      --diffs-hover-mix-target: var(--diffs-decoration-bg);

      --diffs-computed-decoration-bg: light-dark(
        color-mix(
          in lab,
          var(--diffs-bg) var(--mix-deco-light),
          var(--diffs-decoration-bg)
        ),
        color-mix(
          in lab,
          var(--diffs-bg) var(--mix-deco-dark),
          var(--diffs-decoration-bg)
        )
      );
    }
  }

  [data-line-annotation],
  [data-gutter-buffer='annotation'] {
    --diffs-annotation-bg: var(--diffs-bg-context);
    --diffs-computed-decoration-bg: var(--diffs-annotation-bg);
    --diffs-hover-mix-target: var(--diffs-computed-editor-active-line-bg);
  }

  [data-merge-conflict-actions],
  [data-gutter-buffer='merge-conflict-action'],
  [data-gutter-buffer='merge-conflict-marker-base'],
  [data-gutter-buffer='merge-conflict-marker-separator'],
  [data-merge-conflict='marker-base'],
  [data-merge-conflict='marker-separator'] {
    --diffs-computed-decoration-bg: var(--diffs-bg-context);
    --diffs-hover-mix-target: var(--diffs-computed-editor-active-line-bg);
  }

  [data-gutter-buffer='merge-conflict-marker-start'],
  [data-merge-conflict='marker-start'] {
    --diffs-computed-decoration-bg: light-dark(
      color-mix(
        in lab,
        var(--diffs-bg) 78%,
        var(--conflict-bg-current-header-override, var(--diffs-addition-base))
      ),
      color-mix(
        in lab,
        var(--diffs-bg) 68%,
        var(--conflict-bg-current-header-override, var(--diffs-addition-base))
      )
    );
    --diffs-hover-mix-target: var(--diffs-computed-editor-active-line-bg);
  }

  [data-gutter-buffer='merge-conflict-marker-end'],
  [data-merge-conflict='marker-end'] {
    --diffs-computed-decoration-bg: light-dark(
      color-mix(
        in lab,
        var(--diffs-bg) 78%,
        var(--conflict-bg-incoming-header-override, var(--diffs-modified-base))
      ),
      color-mix(
        in lab,
        var(--diffs-bg) 68%,
        var(--conflict-bg-incoming-header-override, var(--diffs-modified-base))
      )
    );
    --diffs-hover-mix-target: var(--diffs-computed-editor-active-line-bg);
  }

  [data-has-merge-conflict] [data-line-annotation],
  [data-has-merge-conflict] [data-gutter-buffer='annotation'] {
    --diffs-computed-decoration-bg: var(--diffs-bg);
    --diffs-hover-mix-target: var(--diffs-computed-editor-active-line-bg);
  }

  /* We are using where here to not affect the nesting impacts later on for
   * hover and selection */
  :where([data-background]) {
    [data-gutter-buffer],
    [data-column-number] {
      --mix-light: 91%;
      --mix-dark: 85%;
    }

    [data-line],
    [data-no-newline] {
      --mix-light: 88%;
      --mix-dark: 80%;
    }

    [data-gutter-buffer],
    [data-column-number],
    [data-line],
    [data-no-newline] {
      --diffs-diff-line-mix-target: var(--diffs-bg);

      &[data-line-type='change-deletion'] {
        --diffs-diff-line-mix-target: var(
          --diffs-bg-deletion-override,
          var(--diffs-deletion-base)
        );
        --diffs-hover-mix-target: var(--diffs-diff-line-mix-target);

        &:where([data-gutter-buffer], [data-column-number]) {
          color: var(
            --diffs-fg-number-deletion-override,
            var(--diffs-deletion-base)
          );

          --diffs-diff-line-mix-target: var(
            --diffs-bg-deletion-number-override,
            var(--diffs-deletion-base)
          );
        }

        --diffs-computed-diff-line-bg: light-dark(
          color-mix(
            in lab,
            var(--diffs-computed-decoration-bg) var(--mix-light),
            var(--diffs-diff-line-mix-target)
          ),
          color-mix(
            in lab,
            var(--diffs-computed-decoration-bg) var(--mix-dark),
            var(--diffs-diff-line-mix-target)
          )
        );
      }

      &[data-line-type='change-addition'] {
        --diffs-diff-line-mix-target: var(
          --diffs-bg-addition-override,
          var(--diffs-addition-base)
        );
        --diffs-hover-mix-target: var(--diffs-diff-line-mix-target);

        &:where([data-gutter-buffer], [data-column-number]) {
          color: var(
            --diffs-fg-number-addition-override,
            var(--diffs-addition-base)
          );

          --diffs-diff-line-mix-target: var(
            --diffs-bg-addition-number-override,
            var(--diffs-addition-base)
          );
        }

        --diffs-computed-diff-line-bg: light-dark(
          color-mix(
            in lab,
            var(--diffs-computed-decoration-bg) var(--mix-light),
            var(--diffs-diff-line-mix-target)
          ),
          color-mix(
            in lab,
            var(--diffs-computed-decoration-bg) var(--mix-dark),
            var(--diffs-diff-line-mix-target)
          )
        );
      }

      &[data-merge-conflict='current'] {
        --diffs-diff-line-mix-target: var(
          --conflict-bg-current-override,
          var(--diffs-addition-base)
        );
        --diffs-hover-mix-target: var(--diffs-diff-line-mix-target);

        &:where([data-gutter-buffer], [data-column-number]) {
          color: var(
            --diffs-fg-number-addition-override,
            var(--diffs-addition-base)
          );

          --diffs-diff-line-mix-target: var(
            --conflict-bg-current-number-override,
            var(--diffs-addition-base)
          );
        }

        --diffs-computed-diff-line-bg: light-dark(
          color-mix(
            in lab,
            var(--diffs-computed-decoration-bg) var(--mix-light),
            var(--diffs-diff-line-mix-target)
          ),
          color-mix(
            in lab,
            var(--diffs-computed-decoration-bg) var(--mix-dark),
            var(--diffs-diff-line-mix-target)
          )
        );
      }

      &[data-merge-conflict='incoming'] {
        --diffs-diff-line-mix-target: var(
          --conflict-bg-incoming-override,
          var(--diffs-modified-base)
        );
        --diffs-hover-mix-target: var(--diffs-diff-line-mix-target);

        &:where([data-gutter-buffer], [data-column-number]) {
          color: var(--diffs-modified-base);

          --diffs-diff-line-mix-target: var(
            --conflict-bg-incoming-number-override,
            var(--diffs-modified-base)
          );
        }

        --diffs-computed-diff-line-bg: light-dark(
          color-mix(
            in lab,
            var(--diffs-computed-decoration-bg) var(--mix-light),
            var(--diffs-diff-line-mix-target)
          ),
          color-mix(
            in lab,
            var(--diffs-computed-decoration-bg) var(--mix-dark),
            var(--diffs-diff-line-mix-target)
          )
        );
      }
    }
  }

  /* Order is important for rationalizing these selectors and for order of
   * application, therefore we need to disable this style-lint rule */
  /* stylelint-disable-next-line no-duplicate-selectors */
  [data-gutter-buffer],
  [data-column-number],
  [data-line],
  [data-line-annotation],
  [data-merge-conflict],
  [data-merge-conflict-actions],
  [data-no-newline],
  [data-editor-overlay] {
    --diffs-selection-mix-target: var(
      --diffs-bg-selection-override,
      var(--diffs-selection-base)
    );
    --diffs-selection-emphasis-mix-target: var(--diffs-selection-mix-target);

    &:where([data-editor-overlay]),
    &:where(
        [data-line],
        [data-line-annotation],
        [data-merge-conflict],
        [data-merge-conflict-actions],
        [data-no-newline]
      )[data-selected-line] {
      --mix-selection-light: 82%;
      --mix-selection-dark: 75%;
      --diffs-hover-mix-target: var(--diffs-selection-mix-target);
    }

    &:where(
      [data-gutter-buffer][data-selected-line],
      [data-column-number]:is([data-selected-line], [data-editor-active-line])
    ) {
      --mix-selection-light: 75%;
      --mix-selection-dark: 60%;
      --diffs-selection-mix-target: var(
        --diffs-bg-selection-number-override,
        var(--diffs-selection-base)
      );
      --diffs-hover-mix-target: var(--diffs-selection-mix-target);
    }

    /* Keep the light-theme emphasis on a selected changed line tied to its
     * resolved diff and selection colors. */
    &:where([data-line][data-selected-line]):is(
        [data-line-type='change-addition'],
        [data-line-type='change-deletion']
      ) {
      --diffs-selection-emphasis-mix-target: light-dark(
        color-mix(
          in lab,
          var(--diffs-diff-line-mix-target, var(--diffs-selection-mix-target))
            var(--mix-selection-light),
          var(--diffs-selection-mix-target)
        ),
        var(--diffs-selection-mix-target)
      );
    }

    &:where([data-editor-overlay]),
    &[data-selected-line] {
      --diffs-computed-selected-line-bg: light-dark(
        color-mix(
          in lab,
          var(--diffs-computed-diff-line-bg) var(--mix-selection-light),
          var(--diffs-selection-mix-target)
        ),
        color-mix(
          in lab,
          var(--diffs-computed-diff-line-bg) var(--mix-selection-dark),
          var(--diffs-selection-mix-target)
        )
      );
    }
  }

  /* The editor's active line sits above selection, but hover remains the final
   * line-background treatment. */
  [data-line][data-editor-active-line],
  [data-column-number][data-editor-active-line] {
    --diffs-computed-editor-active-line-bg: color-mix(
      in lab,
      var(--diffs-computed-selected-line-bg)
        var(--diffs-editor-active-line-source-mix, 100%),
      var(--diffs-selection-emphasis-mix-target)
    );
  }

  @media (pointer: fine) {
    [data-line][data-hovered],
    [data-gutter-buffer][data-hovered],
    [data-column-number][data-hovered],
    [data-line-annotation][data-hovered],
    [data-no-newline][data-hovered],
    [data-merge-conflict][data-hovered],
    [data-merge-conflict-actions][data-hovered],
    [data-editor-overlay][data-hovered] {
      --diffs-computed-hovered-line-bg: light-dark(
        color-mix(
          in lab,
          var(--diffs-computed-editor-active-line-bg) 97%,
          var(--diffs-hover-mix-target)
        ),
        color-mix(
          in lab,
          var(--diffs-computed-editor-active-line-bg) 91%,
          var(--diffs-hover-mix-target)
        )
      );
    }
  }

  [data-gutter-buffer][data-selected-line],
  [data-column-number]:is([data-selected-line], [data-editor-active-line]) {
    color: var(--diffs-selection-number-fg);
  }

  [data-no-newline] {
    user-select: none;

    span {
      opacity: 0.6;
    }
  }

  [data-diff-type='split'][data-overflow='scroll'] {
    display: grid;
    grid-template-columns: 1fr 1fr;

    [data-additions] {
      border-left: 1px solid var(--diffs-bg);
    }

    [data-deletions] {
      border-right: 1px solid var(--diffs-bg);
    }
  }

  [data-code] {
    display: grid;
    grid-auto-flow: dense;
    grid-template-columns: var(--diffs-code-grid);
    overflow: var(--diffs-overflow-override, scroll) clip;
    overscroll-behavior-x: none;
    tab-size: var(--diffs-tab-size, 2);
    align-self: flex-start;
    padding-top: var(--diffs-gap-block, var(--diffs-gap-fallback));
    padding-bottom: max(
      0px,
      calc(
        var(--diffs-gap-block, var(--diffs-gap-fallback)) -
          var(--diffs-scrollbar-gutter)
      )
    );
    scrollbar-gutter: stable;
  }

  [data-diffs-scrollbar-measure] {
    position: absolute;
    top: -200px;
    left: -200px;
    opacity: 0;
    pointer-events: none;
    width: 100px;
    height: 100px;
    padding: 0;
    grid-template-columns: none;
    scrollbar-gutter: auto;
  }

  [data-container-size] {
    container-type: inline-size;
  }

  [data-code]::-webkit-scrollbar {
    width: 0;
    height: var(--diffs-scrollbar-gutter);
  }

  [data-code]::-webkit-scrollbar-track {
    background: transparent;
  }

  [data-code]::-webkit-scrollbar-thumb {
    background-color: transparent;
    border: 1px solid transparent;
    background-clip: content-box;
    border-radius: 3px;
  }

  [data-code]::-webkit-scrollbar-corner {
    background-color: transparent;
  }

  /*
   * If we apply these rules globally it will mean that webkit will opt into the
   * standards compliant version of custom css scrollbars, which we do not want
   * because the custom stuff will look better
  */
  @supports (-moz-appearance: none) {
    [data-code] {
      scrollbar-width: thin;
      scrollbar-color: var(--diffs-bg-context) transparent;
      padding-bottom: var(--diffs-gap-block, var(--diffs-gap-fallback));
    }
  }

  [data-diffs-header] ~ [data-diff],
  [data-diffs-header] ~ [data-file] {
    [data-code],
    &[data-overflow='wrap'],
    &[data-dehydrated][data-diff-type='split'][data-overflow='scroll'] {
      padding-top: 0;
    }
  }

  [data-gutter] {
    display: grid;
    grid-template-rows: subgrid;
    grid-template-columns: subgrid;
    grid-column: 1;
    z-index: 3;
    position: relative;
    background-color: var(--diffs-bg);

    [data-gutter-buffer],
    [data-column-number] {
      border-right: var(--diffs-gap-style, 2px solid var(--diffs-bg));
    }
  }

  [data-content] {
    display: grid;
    grid-template-rows: subgrid;
    grid-template-columns: subgrid;
    grid-column: 2;
    min-width: 0;
    background-color: var(--diffs-bg);
  }

  /* Both split layouts that share one grid across the two columns: wrap
   * always, and scroll while dehydrated. Scroll mode normally renders each
   * column as its own scroll container, where paired annotation rows only get
   * equal heights once the resize manager measures them — before hydration
   * that measurement hasn't run, so the side hosting the annotation content
   * would be taller and the rows below it would shift on hydration. The
   * shared grid gives paired rows equal heights in pure CSS; the dehydrated
   * scroll variant keeps nowrap text and clips horizontal overflow until
   * hydration swaps in the real scroll containers. */
  [data-diff-type='split'][data-overflow='wrap'],
  [data-dehydrated][data-diff-type='split'][data-overflow='scroll'] {
    display: grid;
    grid-auto-flow: dense;
    grid-template-columns: repeat(2, var(--diffs-code-grid));
    padding-block: var(--diffs-gap-block, var(--diffs-gap-fallback));

    [data-code] {
      display: contents;
    }

    [data-deletions] {
      [data-gutter] {
        grid-column: 1;
      }

      [data-content] {
        grid-column: 2;
        border-right: 1px solid var(--diffs-bg);
      }
    }

    [data-additions] {
      [data-gutter] {
        grid-column: 3;
        border-left: 1px solid var(--diffs-bg);
      }

      [data-content] {
        grid-column: 4;
      }
    }
  }

  /* Zeron's component appearance uses the project typography and the
   * Tailwind `py-1.5` spacing value. The marker class is applied by the
   * product wrappers; the unstyled engine appearance keeps its defaults. */
  :host(.zeron-code-block) {
    --diffs-bg: var(--surface-floating);
    --diffs-fg: var(--fg-default);

    font-size: 0.875rem;
    line-height: 1.25rem;

    [data-code] {
      padding-block: 0.375rem;
    }

    [data-diff-type='split'][data-overflow='wrap'],
    [data-dehydrated][data-diff-type='split'][data-overflow='scroll'] {
      padding-block: 0.375rem;
    }
  }

  [data-dehydrated][data-diff-type='split'][data-overflow='scroll']
    [data-content] {
    overflow: clip;
  }

  [data-overflow='scroll'] [data-gutter] {
    position: sticky;
    left: 0;
  }

  [data-interactive-lines] [data-line] {
    cursor: pointer;
  }

  [data-interactive-line-numbers] [data-column-number] {
    cursor: pointer;
    touch-action: none;
  }

  [data-content-buffer],
  [data-gutter-buffer] {
    position: relative;
    user-select: none;
    min-height: 1lh;
  }

  [data-gutter-buffer] {
    padding-left: 2ch;
    padding-right: 1ch;

    &::before {
      content: '';
      display: block;
      min-width: var(
        --diffs-min-number-column-width,
        var(--diffs-min-number-column-width-default, 3ch)
      );
    }
  }

  [data-gutter-buffer='annotation'] {
    --diffs-annotation-bg: var(--diffs-bg-context-gutter);
    min-height: 0;
  }

  [data-gutter-buffer='buffer'] {
    --diffs-line-bg: var(--diffs-bg-context-gutter);
  }

  [data-content-buffer] {
    grid-column: 1;
    /* We multiply by 1.414 (√2) to better approximate the diagonal repeat distance */
    background-size: 8px 8px;
    background-position: 5px 0;
    background-origin: border-box;
    /* This is incredibley expensive... */
    background-image: repeating-linear-gradient(
      -45deg,
      transparent,
      transparent calc(3px * 1.414),
      var(--diffs-bg-buffer) calc(3px * 1.414),
      var(--diffs-bg-buffer) calc(4px * 1.414)
    );
  }

  /* Hunk Separators */
  /* --------------- */
  [data-separator] {
    box-sizing: content-box;
    background-color: var(--diffs-bg);
  }

  [data-separator='simple'] {
    min-height: 4px;
  }

  [data-separator='line-info'],
  [data-separator='line-info-basic'],
  [data-separator='metadata'],
  [data-separator='simple'] {
    background-color: var(--diffs-bg-separator);
  }

  [data-separator='line-info'],
  [data-separator='line-info-basic'],
  [data-separator='metadata'] {
    height: 32px;
    position: relative;
  }

  [data-separator-wrapper] {
    user-select: none;
    fill: currentColor;
    position: absolute;
    inset-inline: 0;
    display: flex;
    align-items: center;
    background-color: var(--diffs-bg);
    height: 100%;
  }

  [data-content] [data-separator-wrapper] {
    display: none;
  }

  [data-separator='metadata'] [data-separator-wrapper] {
    inset-inline: 100% auto;
    padding-inline: 1ch;
    height: 100%;
    background-color: var(--diffs-bg-separator);
    color: var(--diffs-fg-number);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    min-width: min-content;
  }

  [data-separator='line-info'] {
    margin-block: var(--diffs-gap-block, var(--diffs-gap-fallback));

    [data-separator-wrapper] {
      min-width: 16px;
    }
  }

  [data-separator='line-info-basic'],
  [data-separator='metadata'] {
    margin-block: 0;
  }

  [data-separator='line-info'][data-separator-first] {
    margin-top: 0;
  }

  [data-separator='line-info'][data-separator-last] {
    margin-bottom: 0;
  }

  [data-expand-index] [data-separator-wrapper] {
    display: grid;
    grid-template-columns: 32px auto;
  }

  [data-expand-index] [data-separator-wrapper][data-separator-multi-button] {
    grid-template-columns: 32px 32px auto;
  }

  [data-expand-button],
  [data-separator-content] {
    display: flex;
    flex: 0 0 auto;
    align-items: center;
    background-color: var(--diffs-bg-separator);
  }

  [data-expand-index] [data-separator-content]:hover {
    text-decoration: underline;
    cursor: pointer;
  }

  [data-expand-button] {
    appearance: none;
    justify-content: center;
    flex-shrink: 0;
    cursor: pointer;
    min-width: 32px;
    align-self: stretch;
    color: var(--diffs-fg-number);
    border: 0;
    border-right: 2px solid var(--diffs-bg);
    padding: 0;
    font: inherit;

    &:hover {
      color: var(--diffs-fg);
    }

    &[data-expand-all-button] {
      display: none;
    }
  }

  [data-expand-down] [data-icon] {
    transform: scaleY(-1);
  }

  [data-separator-content] {
    flex: 1 1 auto;
    padding: 0 1ch;
    height: 100%;
    color: var(--diffs-fg-number);

    overflow: hidden;
    justify-content: flex-start;
  }

  [data-separator='line-info'],
  [data-separator='line-info-basic'] {
    [data-separator-content] {
      height: 100%;
      user-select: none;
      overflow: clip;
    }
  }

  [data-unmodified-lines] {
    display: block;
    overflow: hidden;
    min-width: 0;
    text-overflow: ellipsis;
    white-space: nowrap;
    flex: 0 1 auto;
  }

  @supports (width: 1cqi) {
    [data-unified] {
      [data-separator='line-info'] [data-separator-wrapper] {
        padding-inline: var(--diffs-gap-inline, var(--diffs-gap-fallback));
        width: 100cqi;

        [data-separator-content] {
          border-radius: 6px;
        }
      }

      [data-separator='line-info'][data-expand-index]
        [data-separator-wrapper]
        [data-separator-content] {
        border-top-left-radius: unset;
        border-bottom-left-radius: unset;
      }
    }

    [data-gutter] {
      [data-separator='line-info'] [data-separator-wrapper] {
        padding-left: var(--diffs-gap-inline, var(--diffs-gap-fallback));
      }

      [data-separator='line-info'] [data-separator-content] {
        border-top-left-radius: 6px;
        border-bottom-left-radius: 6px;
      }

      [data-separator='line-info'][data-expand-index] [data-separator-content] {
        border-top-left-radius: unset;
        border-bottom-left-radius: unset;
      }
    }

    [data-additions] {
      [data-content] [data-separator='line-info'] {
        background-color: var(--diffs-bg);

        [data-separator-wrapper] {
          display: none;
        }
      }

      [data-gutter] [data-separator='line-info'] [data-separator-wrapper] {
        display: block;
        height: 100%;
        background-color: var(--diffs-bg-separator);
        border-top-right-radius: 6px;
        border-bottom-right-radius: 6px;

        [data-separator-content],
        [data-expand-button] {
          display: none;
        }
      }
    }

    [data-overflow='scroll']
      [data-additions]
      [data-gutter]
      [data-separator='line-info']
      [data-separator-wrapper] {
      width: calc(100cqi - var(--diffs-gap-inline, var(--diffs-gap-fallback)));
    }

    [data-overflow='wrap']
      [data-additions]
      [data-content]
      [data-separator='line-info']
      [data-separator-wrapper] {
      background-color: var(--diffs-bg-separator);
      display: block;
      height: 100%;
      margin-right: var(--diffs-gap-inline, var(--diffs-gap-fallback));
      border-top-right-radius: 6px;
      border-bottom-right-radius: 6px;

      [data-separator-content],
      [data-expand-button] {
        display: none;
      }
    }

    [data-separator='line-info'] [data-separator-wrapper] {
      [data-expand-both],
      [data-expand-down],
      [data-expand-up] {
        border-top-left-radius: 6px;
        border-bottom-left-radius: 6px;
      }
    }

    @media (pointer: fine) {
      [data-separator='line-info'] [data-separator-wrapper] {
        &[data-separator-multi-button] {
          [data-expand-up] {
            border-top-left-radius: 6px;
            border-bottom-left-radius: unset;
          }

          [data-expand-down] {
            border-bottom-left-radius: 6px;
            border-top-left-radius: unset;
          }
        }
      }
    }
  }

  @media (pointer: coarse) {
    [data-separator='line-info-basic']
      [data-separator-wrapper][data-separator-multi-button] {
      grid-template-columns: 34px 34px auto;

      [data-separator-content] {
        grid-column: unset;
        grid-row: unset;
      }
    }

    @supports (width: 1cqi) {
      [data-separator='line-info'] [data-separator-wrapper] {
        [data-expand-both],
        [data-expand-down],
        [data-expand-up] {
          border-top-left-radius: 6px;
          border-bottom-left-radius: 6px;
        }

        &[data-separator-multi-button] {
          [data-expand-up] {
            border-top-left-radius: 6px;
            border-bottom-left-radius: 6px;
          }

          [data-expand-down] {
            border-bottom-left-radius: unset;
            border-top-left-radius: unset;
          }
        }
      }
    }
  }

  @media (pointer: fine) {
    [data-separator-wrapper][data-separator-multi-button] {
      display: grid;
      grid-template-rows: 50% 50%;

      [data-separator-content] {
        grid-column: 2;
        grid-row: 1 / -1;
        min-width: min-content;
      }

      [data-expand-button] {
        grid-column: 1;
      }
    }

    [data-separator='line-info'] [data-separator-wrapper],
    [data-separator='line-info']
      [data-separator-wrapper][data-separator-multi-button] {
      grid-template-columns: 34px auto;
    }

    [data-separator='line-info-basic'][data-expand-index]
      [data-separator-wrapper] {
      grid-template-columns: 100% auto;
    }

    [data-separator='line-info'],
    [data-separator='line-info-basic'] {
      [data-separator-multi-button] {
        [data-expand-up] {
          border-bottom: 1px solid var(--diffs-bg);
          border-right: 2px solid var(--diffs-bg);
        }
        [data-expand-down] {
          border-top: 1px solid var(--diffs-bg);
          border-right: 2px solid var(--diffs-bg);
        }
      }
    }
  }

  /* Hunk separator content is duplicated across gutters and content columns,
   * so custom CSS can do some stuff. Lets hide things for defaults */
  [data-additions] [data-gutter] [data-separator-wrapper],
  [data-additions] [data-separator='line-info-basic'] [data-separator-wrapper],
  [data-content] [data-separator-wrapper] {
    display: none;
  }

  [data-line-annotation] {
    min-height: var(--diffs-annotation-min-height, 0);
    z-index: 2;
  }

  [data-merge-conflict-actions] {
    z-index: 2;
  }

  [data-separator='custom'] {
    display: grid;
    grid-template-columns: subgrid;
  }

  [data-line],
  [data-column-number],
  [data-no-newline] {
    position: relative;
    padding-inline: 1ch;
  }

  [data-indicators='classic'] [data-line] {
    padding-inline-start: 2ch;
  }

  [data-indicators='classic'] {
    [data-line-type='change-addition'],
    [data-line-type='change-deletion'] {
      &[data-no-newline],
      &[data-line] {
        &::before {
          display: inline-block;
          width: 1ch;
          height: 1lh;
          position: absolute;
          top: 0;
          left: 0;
          user-select: none;
        }
      }
    }

    [data-line-type='change-addition'] {
      &[data-line],
      &[data-no-newline] {
        &::before {
          content: '+';
          color: var(--diffs-addition-base);
        }
      }
    }

    [data-line-type='change-deletion'] {
      &[data-line],
      &[data-no-newline] {
        &::before {
          content: '-';
          color: var(--diffs-deletion-base);
        }
      }
    }
  }

  [data-indicators='bars'] {
    [data-line-type='change-deletion'],
    [data-line-type='change-addition'] {
      &[data-column-number] {
        &::before {
          content: '';
          display: block;
          width: 4px;
          height: 100%;
          position: absolute;
          top: 0;
          left: 0;
          user-select: none;
          contain: strict;
        }
      }
    }

    [data-line-type='change-deletion'] {
      &[data-column-number] {
        &::before {
          background-image: linear-gradient(
            0deg,
            var(--diffs-bg-deletion) 50%,
            var(--diffs-deletion-base) 50%
          );
          background-repeat: repeat;
          background-size: 2px 2px;
          background-size: calc(1lh / round(1lh / 2px))
            calc(1lh / round(1lh / 2px));
        }
      }
    }

    [data-line-type='change-addition'] {
      &[data-column-number] {
        &::before {
          background-color: var(--diffs-addition-base);
        }
      }
    }
  }

  [data-overflow='wrap'] {
    [data-line] {
      white-space: pre-wrap;
      word-break: break-word;
    }

    /* Annotations wrap in every overflow mode (see the base
     * [data-annotation-content] rule). In wrap mode, also break long words so
     * they do not overflow the wrapped column. */
    [data-annotation-content] {
      word-break: break-word;
    }
  }

  [data-overflow='scroll'] [data-line] {
    white-space: pre;
    min-height: 1lh;
  }

  [data-column-number] {
    box-sizing: content-box;
    text-align: right;
    user-select: none;
    color: var(--diffs-fg-number);
    padding-left: 2ch;
  }

  [data-line-number-content] {
    display: inline-block;
    min-width: var(
      --diffs-min-number-column-width,
      var(--diffs-min-number-column-width-default, 3ch)
    );
    position: relative;
    z-index: 1;
  }

  [data-disable-line-numbers] {
    [data-gutter-buffer],
    [data-column-number] {
      min-width: 4px;
      padding: 0;

      &::before {
        min-width: 0;
      }
    }

    [data-line-number-content] {
      display: none;
    }

    [data-gutter-utility-slot] {
      right: unset;
      left: 0;
      justify-content: flex-start;
    }

    &[data-indicators='bars'] [data-gutter-utility-slot] {
      /* Using 5px here because theres a 2px separator after the bar */
      left: 6px;
    }
  }

  [data-file][data-disable-line-numbers] {
    [data-gutter-buffer],
    [data-column-number] {
      min-width: 0;
      border-right: 0;
    }
  }

  [data-diff-span] {
    border-radius: 3px;
    box-decoration-break: clone;
  }

  [data-line-type='change-addition'] [data-diff-span] {
    background-color: var(--diffs-bg-addition-emphasis);
  }

  [data-line-type='change-deletion'] [data-diff-span] {
    background-color: var(--diffs-bg-deletion-emphasis);
  }

  [data-merge-conflict='marker-start'],
  [data-merge-conflict='marker-base'],
  [data-merge-conflict='marker-separator'],
  [data-merge-conflict='marker-end'] {
    padding-left: 1ch;
    color: var(--diffs-fg);
  }

  [data-merge-conflict='marker-start'],
  [data-merge-conflict='marker-end'] {
    display: flex;
    align-items: center;

    &::after {
      color: var(--diffs-fg-conflict-marker);
      font-style: normal;
      font-size: 0.75rem;
      line-height: 1.25rem;
      padding-left: 1ch;
      font-family: var(
        --diffs-header-font-family,
        var(--diffs-header-font-fallback)
      );
    }
  }

  [data-merge-conflict='marker-start']::after {
    content: '(' attr(data-merge-conflict-marker-label) ')';
  }

  [data-merge-conflict='marker-end']::after {
    content: '(' attr(data-merge-conflict-marker-label) ')';
  }

  [data-merge-conflict-actions-content] {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    padding-inline: 0.5rem;
    min-height: 1.75rem;
    font-family: var(
      --diffs-header-font-family,
      var(--diffs-header-font-fallback)
    );
    font-size: 0.75rem;
    line-height: 1.2;
    color: var(--diffs-fg);
  }

  [data-merge-conflict-action] {
    appearance: none;
    border: 0;
    background: transparent;
    color: var(--diffs-fg-number);
    font: inherit;
    font-style: normal;
    cursor: pointer;
    padding: 0;
  }

  [data-merge-conflict-action]:hover {
    color: var(--diffs-fg);
  }

  [data-merge-conflict-action='current']:hover {
    color: var(--diffs-addition-base);
  }

  [data-merge-conflict-action='incoming']:hover {
    color: var(--diffs-modified-base);
  }

  [data-merge-conflict-action-separator] {
    color: var(--diffs-fg-number);
    opacity: 0.6;
    user-select: none;
  }

  /* Default Header Styles */
  /* --------------------- */
  [data-diffs-header='default'] {
    position: relative;
    background-color: var(--diffs-bg);
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    gap: var(--diffs-gap-inline, var(--diffs-gap-fallback));
    min-height: calc(
      1lh + (var(--diffs-gap-block, var(--diffs-gap-fallback)) * 3)
    );
    padding-inline: 16px;
    top: 0;
    z-index: 2;
  }

  [data-header-content] {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: var(--diffs-gap-inline, var(--diffs-gap-fallback));
    min-width: 0;
    white-space: nowrap;
  }

  [data-header-content] [data-prev-name],
  [data-header-content] [data-title] {
    direction: rtl;
    overflow: hidden;
    text-overflow: ellipsis;
    min-width: 0;
    white-space: nowrap;
  }

  [data-prev-name] {
    opacity: 0.7;
  }

  [data-rename-icon] {
    fill: currentColor;
    flex-shrink: 0;
    flex-grow: 0;
  }

  [data-diffs-header='default'] [data-metadata] {
    display: flex;
    align-items: center;
    gap: 1ch;
    white-space: nowrap;
  }

  [data-diffs-header='default'] [data-additions-count] {
    font-family: var(--diffs-font-family, var(--diffs-font-fallback));
    color: var(--diffs-addition-base);
  }

  [data-diffs-header='default'] [data-deletions-count] {
    font-family: var(--diffs-font-family, var(--diffs-font-fallback));
    color: var(--diffs-deletion-base);
  }

  [data-change-icon] {
    fill: currentColor;
    flex-shrink: 0;
  }

  [data-change-icon='change'],
  [data-change-icon='rename-pure'],
  [data-change-icon='rename-changed'] {
    color: var(--diffs-modified-base);
  }

  [data-change-icon='new'] {
    color: var(--diffs-addition-base);
  }

  [data-change-icon='deleted'] {
    color: var(--diffs-deletion-base);
  }

  [data-change-icon='file'] {
    opacity: 0.6;
  }

  [data-annotation-content] {
    position: relative;
    display: flow-root;
    align-self: flex-start;
    z-index: 2;
    min-width: 0;
    isolation: isolate;
    /* Annotations contain prose, not code. The text must wrap in every
     * overflow mode. Slotted annotation content inherits this white-space
     * value. In scroll mode without this rule, the text inherits
     * `white-space: pre` from the `pre` element. Then long text does not
     * wrap. */
    white-space: normal;
  }

  /* Sticky positioning has a composite costs, so we should _only_ pay it if we
   * need to */
  [data-overflow='scroll'] [data-annotation-content] {
    position: sticky;
    width: var(--diffs-column-content-width, auto);
    left: var(--diffs-column-number-width, 0);
  }

  [data-overflow='scroll'] [data-merge-conflict-actions-content] {
    position: sticky;
    width: var(--diffs-column-content-width, auto);
    left: var(--diffs-column-number-width, 0);
  }

  /* Undo some of the stuff that the 'pre' tag does */
  [data-annotation-slot] {
    text-wrap-mode: wrap;
    word-break: normal;
    white-space-collapse: collapse;
  }

  [data-gutter-utility-slot] {
    position: absolute;
    top: 0;
    bottom: 0;
    right: 0;
    display: flex;
    justify-content: flex-end;
    touch-action: none;
  }

  [data-utility-button] {
    display: flex;
    align-items: center;
    justify-content: center;
    border: none;
    appearance: none;
    width: 1lh;
    height: 1lh;
    margin-right: calc((1lh - 1ch) * -1);
    padding: 0;
    cursor: pointer;
    font-size: var(--diffs-font-size, inherit);
    line-height: var(--diffs-line-height, inherit);
    border-radius: 4px;
    background-color: var(--diffs-modified-base);
    color: var(--diffs-bg);
    fill: currentColor;
    position: relative;
    z-index: 4;
    touch-action: none;

    &::before {
      content: '';
      display: block;
      position: absolute;
      inset: 0 0 0 -4px;
    }
  }

  /* Decoration Bars */
  /* --------------- */
  [data-decoration-bar-stack] {
    position: absolute;
    top: 0;
    bottom: 0;
    right: -2px;
    width: 6px;
    pointer-events: none;
    isolation: isolate;
    z-index: 1;
    background-color: var(--diffs-decoration-bar-color, transparent);
    /* overflow: clip visible; */
    box-sizing: content-box;
    border-left: 2px solid var(--diffs-bg);
    border-right: 2px solid var(--diffs-bg);

    [data-decoration-bar-depth='1'] & {
      background-color: color-mix(
        in lab,
        var(--diffs-bg) 20%,
        var(--diffs-decoration-bar-color, transparent)
      );
    }

    [data-decoration-bar-depth='2'] & {
      background-color: color-mix(
        in lab,
        var(--diffs-bg) 45%,
        var(--diffs-decoration-bar-color, transparent)
      );
    }

    [data-decoration-bar-depth='3'] & {
      background-color: color-mix(
        in lab,
        var(--diffs-bg) 65%,
        var(--diffs-decoration-bar-color, transparent)
      );
    }

    [data-decoration-bar-start] & {
      border-top-left-radius: 5px;
      border-top-right-radius: 5px;

      /* &::before { */
      /*   content: ''; */
      /*   position: absolute; */
      /*   box-sizing: content-box; */
      /*   display: block; */
      /*   width: 6px; */
      /*   height: 6px; */
      /*   z-index: 1; */
      /*   border-top-left-radius: 3px; */
      /*   border-top-right-radius: 3px; */
      /*   border-top: 2px solid var(--diffs-bg); */
      /*   border-left: 2px solid var(--diffs-bg); */
      /*   border-right: 2px solid var(--diffs-bg); */
      /*   left: -2px; */
      /*   top: -2px; */
      /* } */
    }

    [data-decoration-bar-end] & {
      z-index: 3;
      border-bottom-left-radius: 5px;
      border-bottom-right-radius: 5px;

      /* &::after { */
      /*   content: ''; */
      /*   position: absolute; */
      /*   box-sizing: content-box; */
      /*   display: block; */
      /*   width: 6px; */
      /*   height: 6px; */
      /*   border-bottom-left-radius: 3px; */
      /*   border-bottom-right-radius: 3px; */
      /*   border-bottom: 2px solid var(--diffs-bg); */
      /*   border-left: 2px solid var(--diffs-bg); */
      /*   border-right: 2px solid var(--diffs-bg); */
      /*   left: -2px; */
      /*   bottom: -2px; */
      /* } */
    }

    /* [data-decoration-bar-end] & { */
    /*   border-bottom-left-radius: 5px; */
    /*   border-bottom-right-radius: 5px; */
    /*   border-bottom: 2px solid var(--diffs-bg); */
    /*   border-left: 2px solid var(--diffs-bg); */
    /*   border-right: 2px solid var(--diffs-bg); */
    /*   right: -2px; */
    /*   bottom: -2px; */
    /*   z-index: 3; */
    /* } */
  }

  [data-placeholder] {
    contain: strict;
  }

  [data-error-wrapper] {
    overflow: auto;
    padding: var(--diffs-gap-block, var(--diffs-gap-fallback))
      var(--diffs-gap-inline, var(--diffs-gap-fallback));
    max-height: 400px;
    scrollbar-width: none;

    [data-error-message] {
      font-weight: bold;
      font-size: 18px;
      color: var(--diffs-deletion-base);
    }

    [data-error-stack] {
      color: var(--diffs-fg-number);
    }
  }
}

::selection {
  background-color: transparent;
}

/* Read-only deletion text sits outside the editor's selection overlay, so the
   global transparent ::selection above hides its selection by default. Reveal
   the native selection (so users can see what they select and copy) only while
   the user is actively selecting within deleted text: the editor sets
   data-deleted-text-selection on the diff while a pointer gesture starts there.
   Gating it this way means a normal selection of editable code that merely
   sweeps across an interleaved deleted line (unified view) does not highlight
   that line. Covers the whole deletions column in split view and individual
   deleted lines in unified view. */
[data-deleted-text-selection] [data-deletions] ::selection,
[data-deleted-text-selection] [data-line-type='change-deletion'] ::selection {
  background-color: var(--diffs-editor-selection-bg);
}

@keyframes blinking {
  0% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

:host, /* for scroll anchor */
[data-code], /* for editor overlay */
[data-content] /* for wrap line measurement */,
[data-diff-type='split'][data-overflow='wrap'] {
  position: relative;
}
[data-code] {
  container-type: inline-size;
}
[data-content] {
  cursor: text;
  background-color: transparent;
  caret-color: var(--diffs-bg-caret);
  outline: none;
}
[data-line] {
  cursor: text;
  /* Transparent so the line's in-flow background can't hide the selection
     overlay (z-index -10); the line color moves to the ::after layer below it. */
  background-color: transparent;
}
/* Line background layer below the selection overlay (z-index -10) so the
   translucent selection composites over it. ::before is the +/- indicator. */
[data-line]::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -20;
  background-color: var(--diffs-line-bg);
  pointer-events: none;
}
/* The line-state pipeline resolves the active background. Keep the theme's
   border as an additional cue, including for border-only themes. */
[data-line][data-editor-active-line]::after {
  box-shadow: inset 0 0 0 1px var(--diffs-editor-line-highlight-border);
}

[data-editor-overlay] {
  display: contents;
}
[data-caret],
[data-edit-prediction],
[data-selection-range],
[data-match-range],
[data-bracket-match-range],
[data-edit-prediction-deletion-range],
[data-edit-prediction-insertion-range],
[data-edit-prediction-replacement-range],
[data-marker-range],
[data-remote-caret],
[data-caret-highlight-range] {
  position: absolute;
  top: 0;
  left: 0;
  height: 1lh;
  line-height: var(--diffs-line-height, inherit);
  pointer-events: none;
}
[data-edit-prediction] {
  z-index: 1;
  height: auto;
  overflow: visible;
  width: max-content;
  user-select: none;
  color: var(
    --diffs-editor-edit-prediction-fg,
    color-mix(in lab, var(--diffs-fg) 45%, transparent)
  );
}
[data-edit-prediction-line] {
  box-sizing: border-box;
  display: block;
  min-height: 1lh;
  width: max-content;
  white-space: pre;
}
[data-edit-prediction][data-replacement] [data-edit-prediction-line],
[data-edit-prediction-insertion-range],
[data-edit-prediction-replacement-range] {
  background-color: var(--diffs-edit-prediction-bg, var(--diffs-bg));
}
[data-edit-prediction-suffix] {
  color: var(--diffs-fg);
}
[data-edit-prediction][data-wrap] [data-edit-prediction-line] {
  max-width: 100%;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
}
[data-edit-prediction-line][data-empty]::after {
  content: '↵';
}
[data-edit-prediction-spacer] {
  margin-block-end: var(--diffs-edit-prediction-spacer-height);
}
/* The deletions column of a split diff shows no ghost text, so its reserved
   rows are padding: the row tint and the buffer hatch extend over them instead
   of leaving a blank strip. Buffers size themselves with a border-box
   min-height that would absorb the padding, hence content-box. */
[data-code][data-deletions] [data-edit-prediction-spacer] {
  margin-block-end: 0;
  padding-block-end: var(--diffs-edit-prediction-spacer-height);
  box-sizing: content-box;
}
[data-edit-prediction-deletion-range] {
  --diffs-edit-prediction-deletion-color: var(
    --diffs-editor-edit-prediction-deletion-fg,
    color-mix(in lab, var(--diffs-deletion-base) 70%, transparent)
  );

  z-index: 1;
  background: linear-gradient(
    to bottom,
    transparent calc(50% - 0.5px),
    var(--diffs-edit-prediction-deletion-color) calc(50% - 0.5px),
    var(--diffs-edit-prediction-deletion-color) calc(50% + 0.5px),
    transparent calc(50% + 0.5px)
  );
}
[data-edit-prediction-insertion-range] {
  z-index: 0;
}
[data-edit-prediction-replacement-range] {
  z-index: 1;
}
[data-caret] {
  z-index: 2;
  width: 2px;
  background-color: var(
    --diffs-bg-caret-override,
    var(
      --diffs-editor-cursor-fg,
      light-dark(
        color-mix(in lab, var(--diffs-fg) 50%, var(--diffs-bg)),
        color-mix(in lab, var(--diffs-fg) 75%, var(--diffs-bg))
      )
    )
  );
  visibility: hidden;
}
/* Reduce motion only if user has set a preference */
@media (prefers-reduced-motion: no-preference) {
  [data-caret] {
    animation: blinking 1.2s infinite;
    animation-delay: 0.8s;
  }
}
[data-selection-range] {
  z-index: -10;
  background-color: var(--diffs-editor-selection-bg);
}
[data-caret-highlight-range] {
  z-index: -10;
  background-color: var(
    --diffs-caret-highlight-bg,
    var(--diffs-editor-selection-bg)
  );
}
/* Masks the selection's square corner to fake rounding, so it must match the bg
   behind the selection: the line's diff color (passed in via
   --diffs-selection-corner-bg) or the editor base for context lines. */
[data-selection-corner] {
  width: 100%;
  height: 100%;
  background-color: var(--diffs-selection-corner-bg, var(--diffs-bg));
}
[data-match-range] {
  z-index: -10;
  background-color: var(
    --diffs-editor-match-bg,
    var(--diffs-editor-selection-bg)
  );
}
[data-match-range]:not([data-focus]) {
  background-color: var(
    --diffs-editor-match-highlight-bg,
    light-dark(#ff963288, #ff963266)
  );
}
[data-bracket-match-range] {
  z-index: -9;
  box-sizing: border-box;
  border-bottom: 1px solid
    var(
      --diffs-editor-bracket-match-border,
      color-mix(in lab, var(--diffs-fg) 60%, transparent)
    );
  background-color: var(
    --diffs-editor-bracket-match-bg,
    color-mix(in lab, var(--diffs-fg) 5%, transparent)
  );
}

[data-rtl] {
  border-top-left-radius: 3px;
}
[data-rtr] {
  border-top-right-radius: 3px;
}
[data-rbl] {
  border-bottom-left-radius: 3px;
}
[data-rbr] {
  border-bottom-right-radius: 3px;
}

/* Markers
 *
 * Marker range applies a wavy underline. Severity attributes are used by both
 * `[data-marker-range]` and `[data-marker-popover]` alike.
 */

[data-marker-range] {
  z-index: 1;
  background-color: var(--diffs-marker-bg);
  mask-image: url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI2IiBoZWlnaHQ9IjMiPjxwYXRoIGQ9Im0wIDIuNSBsMiAtMS41IGwxIDAgbDIgMS41IGwxIDAiIHN0cm9rZT0iI2ZmZiIgZmlsbD0ibm9uZSIgc3Ryb2tlLXdpZHRoPSIxIi8+PC9zdmc+');
  mask-position: left bottom;
  mask-repeat: repeat-x;
  mask-size: 6px 3px;
}

[data-marker-error] {
  --diffs-marker-contrast: light-dark(#fff, #000);
  --diffs-marker-bg: var(--diffs-editor-error-fg, var(--diffs-deletion-base));
}
[data-marker-warning] {
  --diffs-marker-contrast: #000;
  --diffs-marker-bg: var(
    --diffs-editor-warning-fg,
    light-dark(var(--diffs-warning-light), var(--diffs-warning-dark))
  );
}
[data-marker-info] {
  --diffs-marker-contrast: #000;
  --diffs-marker-bg: var(--diffs-editor-info-fg, var(--diffs-modified-base));
}
[data-marker-hint] {
  --diffs-marker-contrast: light-dark(#fff, #000);
  --diffs-marker-bg: var(--diffs-editor-hint-fg, var(--diffs-fg-number));
}

@media (width >= 480px) {
  [data-content] {
    caret-color: transparent;
  }
  [data-content]:focus ~ [data-editor-overlay] [data-caret] {
    visibility: visible;
  }
}

/* Editor widgets
 *
 * Positioned popovers used across edit mode. Used by markers, search panel,
 * and selection action.
 */

[data-editor-widget] {
  --diffs-widget-fg: var(--diffs-fg);
  --diffs-widget-bg: color-mix(in lab, var(--diffs-fg) 4%, var(--diffs-bg));
  --diffs-widget-border: color-mix(in lab, var(--diffs-fg) 20%, transparent);
  --diffs-widget-shadow:
    inset 0 0 0 1px var(--diffs-bg), 0 4px 8px rgb(0 0 0 / 0.075),
    0 6px 18px rgb(0 0 0 / 0.075);
  position: absolute;
  top: 0;
  left: 0;
  z-index: 100;
  width: fit-content;
  max-width: calc(100% - 24px);
  font: 14px/20px var(--diffs-header-font-fallback);
  border: 1px solid var(--diffs-widget-border);
  border-radius: 9px;
  background-color: var(--diffs-widget-bg);
  background-clip: padding-box;
  box-shadow: var(--diffs-widget-shadow);
}

/* Shared geometry for the overlay popovers (marker hover popover and
   selection-action popover). Both are positioned in overlay coordinate space via
   --popover-x/--popover-y (set in JS). The left edge is clamped so the popover
   never slides under the line-number gutter (--gutter-width, also set in JS) or
   outside the visible scroll viewport, and the width is capped to match. Builds
   on [data-editor-widget]. */
[data-marker-popover],
[data-selection-action-popover] {
  --popover-gap: var(--diffs-popover-gap, var(--diffs-gap-fallback, 8px));
  --popover-viewport-left: 0px;
  --popover-viewport-right: 100cqw;
  /* Sentinels disable the vertical clamp until JS sets the real scrollport. */
  --popover-viewport-top: -99999px;
  --popover-viewport-bottom: 99999px;
  --popover-min-left: calc(
    var(--popover-viewport-left) + var(--gutter-width, 0px) + var(--popover-gap)
  );
  --popover-available-width: max(
    0px,
    calc(
      var(--popover-viewport-right) - var(--popover-min-left) -
        var(--popover-gap)
    )
  );
  max-width: min(640px, var(--popover-available-width));
  translate: clamp(
      var(--popover-min-left),
      var(--popover-x, var(--popover-min-left)),
      calc(var(--popover-viewport-right) - var(--popover-gap) - 100%)
    )
    /* Clamp into the scrollport so a popover with no fitting side stays in view. */
    clamp(
      var(--popover-viewport-top),
      calc(var(--popover-y, 0px) + var(--popover-y-shift, 0px)),
      calc(var(--popover-viewport-bottom) - var(--popover-gap) - 100%)
    );
}

[data-marker-popover] {
  --diffs-widget-bg: var(--diffs-marker-bg);
  --diffs-widget-shadow:
    0 4px 8px rgb(0 0 0 / 0.15), 0 6px 18px rgb(0 0 0 / 0.15);

  padding: 8px 12px;
  min-width: min(180px, var(--popover-available-width));
  overflow-wrap: anywhere;
  color: var(--diffs-marker-contrast);
  white-space: normal;
  border: 0;
  pointer-events: auto;

  @supports (color: contrast-color(red)) {
    color: contrast-color(var(--diffs-marker-bg, var(--diffs-bg)));
  }

  [data-marker-message] {
    white-space: normal;
    overflow-wrap: anywhere;

    code {
      display: inline;
      background-color: transparent;
      white-space: normal;
      color: inherit;
    }
  }
}

/* Selection Action Widget: a floating popover hosting the consumer's
   selection-action element. It reuses the shared [data-editor-widget] chrome and
   sits in the overlay layer (which is pointer-events: none), so it re-enables
   pointer events for its own actions. */
[data-selection-action-popover] {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
  width: max-content;
  padding: 4px;
  pointer-events: auto;
}

/* Search Panel Widget */
[data-search-panel] {
  position: sticky;
  top: 16px;
  right: 16px;
  z-index: 100;
  display: flex;
  justify-content: right;
  flex-direction: column;
  width: 100%;
  /* Zero height ensures panel appears stickied immediately */
  height: 0;
  container: search-panel / inline-size;

  [data-editor-widget] {
    position: relative;
    z-index: 100;
    display: flex;
    flex-shrink: 0;
    align-items: stretch;
    gap: 8px;
    padding: 4px;
    max-width: 100%;
    min-width: 260px;
    margin-inline: auto 16px;
  }

  svg {
    display: block;
    fill: currentColor;
    width: 12px;
    height: 12px;
  }
}

[data-search-grid] {
  display: grid;
  grid-template-columns: auto auto auto;
  grid-template-areas:
    'find    matches nav'
    'replace actions .';
  align-items: center;
  gap: 4px 6px;
  width: 100%;
}
[data-input-box][data-find] {
  grid-area: find;
}
[data-search-nav] {
  grid-area: nav;
}
[data-input-box][data-replace] {
  grid-area: replace;
}
[data-replace-actions] {
  grid-area: actions;
}
[data-search-grid][data-mode='find'] {
  grid-template-areas: 'find matches nav';
}
[data-search-grid][data-mode='find'] [data-replace-cell] {
  display: none;
}

@container search-panel (width < 400px) {
  [data-search-panel] [data-editor-widget] {
    padding: 10px;
  }
  [data-search-grid][data-mode='replace'] {
    grid-template-columns: auto 1fr auto;
    grid-template-areas:
      'find    find    find'
      'replace replace replace'
      'nav     matches actions';
  }
  [data-search-grid][data-mode='find'] {
    grid-template-columns: auto 1fr auto;
    grid-template-areas:
      'find find    find'
      'nav  matches matches';
  }
  [data-replace-actions] {
    justify-self: end;
  }
  [data-search-grid] [data-input-box] {
    width: auto;
  }
}

[data-input-box] {
  position: relative;
  display: flex;
  align-items: center;
  width: 200px;

  input {
    flex-grow: 1;
    width: 100%;
    min-width: 0;
    font-size: 13px;
    line-height: 24px;
    padding-inline: 6px;
    color: var(--diffs-fg);
    background-color: var(--diffs-bg);
    border: 1px solid color-mix(in lab, var(--diffs-fg) 12%, var(--diffs-bg));
    border-radius: 6px;
    outline: none;

    &::selection {
      background-color: color-mix(in lab, var(--diffs-fg) 8%, var(--diffs-bg));
    }

    &:focus-visible {
      outline: 1px solid var(--diffs-modified-base);
    }
  }

  &[data-find] input {
    /* Space for overlaid search icon toggles */
    padding-inline-end: 72px;
  }

  [data-search-icon] {
    --diffs-search-icon-size: 20px;
  }
}

[data-search-toggles] {
  position: absolute;
  top: 50%;
  right: 4px;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  gap: 1px;
}

[data-matches] {
  grid-area: matches;
  flex-shrink: 0;
  min-width: 50px;
  font-size: 12px;
  font-weight: 500;
  line-height: 20px;
  white-space: nowrap;
  color: color-mix(in lab, var(--diffs-fg) 50%, var(--diffs-bg));

  &[data-no-matches] {
    color: color-mix(in lab, var(--diffs-fg) 35%, var(--diffs-bg));
  }
}

[data-replace-actions],
[data-search-nav] {
  display: flex;
  align-items: center;
}

/* Every clickable control is a real <button> tagged with data-search-icon;
   strip the UA chrome here so this single rule is the source of their
   appearance. */
[data-search-icon] {
  display: flex;
  align-items: center;
  justify-content: center;
  appearance: none;
  flex-shrink: 0;
  width: var(--diffs-search-icon-size, 24px);
  height: var(--diffs-search-icon-size, 24px);
  margin: 0;
  padding: 0;
  color: color-mix(in lab, var(--diffs-fg) 65%, var(--diffs-bg));
  border: 0;
  border-radius: var(--diffs-search-icon-radius, 4px);
  background: none;
  cursor: pointer;
  transition:
    background-color 0.1s ease-in-out,
    color 0.1s ease-in-out;

  &:disabled {
    opacity: 0.25;
    cursor: default;
  }
  &:not(:disabled):hover {
    color: var(--diffs-fg);
  }
  &:focus-visible {
    outline: 1px solid var(--diffs-modified-base);
  }
  &[aria-pressed='true'] {
    color: var(--diffs-modified-base);
  }
}

[data-search-close] {
  --diffs-search-icon-size: 20px;
  --diffs-search-icon-radius: 50%;
  position: absolute;
  top: 0;
  right: 0;
  transform: translate(50%, -50%);
  color: var(--diffs-widget-bg);
  background-color: color-mix(
    in lab,
    var(--diffs-widget-fg) 50%,
    var(--diffs-bg)
  );

  &:not(:disabled):hover {
    opacity: 1;
    color: var(--diffs-widget-bg);
    background-color: var(--diffs-widget-fg);
  }
}

