        string,
        TTheme
    ]>): void {
        for (const [name, theme] of entries) {
            seedResolvedTheme(name, theme);
        }
    }
    function getResolvedTheme(name: string): TTheme | undefined {
        return resolved.get(name);
    }
    function getResolvedThemes(names: readonly string[]): TTheme[] {
        const themes: TTheme[] = [];
