 * Empty collections return true because they are valid for either shape.
 */
export function isDiffAnnotationCollection<LAnnotation = undefined>(annotations: LineAnnotation<LAnnotation>[] | DiffLineAnnotation<LAnnotation>[]): annotations is DiffLineAnnotation<LAnnotation>[] {
    const first = annotations[0];
    return first == null || isDiffAnnotation(first);
