 * Empty collections return true because they are valid for either shape.
 */
export function isFileAnnotationCollection<LAnnotation = undefined>(annotations: LineAnnotation<LAnnotation>[] | DiffLineAnnotation<LAnnotation>[]): annotations is LineAnnotation<LAnnotation>[] {
    const first = annotations[0];
    return first == null || isFileAnnotation(first);
}

// Appends every entry of `items` onto `target` one at a time. Deliberately not
// `target.push(...items)`: a spread passes one argument per entry and engines
// cap argument counts (V8 near 124k, JavaScriptCore near 639k), so spreading a
// line-sized array such as the rows of a massive hunk throws a RangeError.
export function appendItems<T>(target: T[], items: readonly T[]): void {
    for (const item of items) {
        target.push(item);
    }
}

// Editor token text omits line endings; renderer line caches (diff
// `additionLines`, FileRenderer's split-line cache) keep the suffix from
// parsing. Re-apply the previous line's ending so edited text can be written
// back into those caches without corrupting reconstructed file contents.
export function applyLineTextWithNewline(line: string, lineText: string): string {
    if (line.endsWith('\r\n')) {
        return lineText + '\r\n';
    }
    if (line.endsWith('\r')) {
        return lineText + '\r';
    }
    if (line.endsWith('\n')) {
        return lineText + '\n';
    }
    return lineText;
}

import type { DiffLineAnnotation } from '../types';
export function areDiffLineAnnotationsEqual<LAnnotation = undefined>(annotationA: DiffLineAnnotation<LAnnotation>, annotationB: DiffLineAnnotation<LAnnotation>): boolean {
    return (annotationA.lineNumber === annotationB.lineNumber &&
        annotationA.side === annotationB.side &&
        annotationA.metadata === annotationB.metadata);
}

import type { RenderDiffOptions } from '../types';
import { areThemesEqual } from './areThemesEqual';
export function areDiffRenderOptionsEqual(optionsA: RenderDiffOptions, optionsB: RenderDiffOptions): boolean {
    return (areThemesEqual(optionsA.theme, optionsB.theme) &&
        optionsA.useTokenTransformer === optionsB.useTokenTransformer &&
        optionsA.tokenizeMaxLineLength === optionsB.tokenizeMaxLineLength &&
        optionsA.lineDiffType === optionsB.lineDiffType &&
        optionsA.maxLineDiffLength === optionsB.maxLineDiffLength);
}

import type { FileDiffMetadata } from '../types';
// Because FileDiffMetadata is a potentially unbounded and structurally deep
// object, we only check for top level equality or a cache key, otherwise we
// just assume it's different every time
export function areDiffTargetsEqual(diffA: FileDiffMetadata | undefined, diffB: FileDiffMetadata | undefined): boolean {
    return diffA?.cacheKey != null || diffB?.cacheKey != null
        ? diffA?.cacheKey === diffB?.cacheKey
        : diffA === diffB;
}

import type { RenderFileOptions } from '../types';
import { areThemesEqual } from './areThemesEqual';
export function areFileRenderOptionsEqual(optionsA: RenderFileOptions, optionsB: RenderFileOptions): boolean {
    return (areThemesEqual(optionsA.theme, optionsB.theme) &&
        optionsA.useTokenTransformer === optionsB.useTokenTransformer &&
        optionsA.tokenizeMaxLineLength === optionsB.tokenizeMaxLineLength);
}

