import type { CodeViewRenderedItem, CodeViewSlotSnapshot, } from '../components/CodeView';
export function areManagedSnapshotsEqual<LAnnotation, Caret>(previous: CodeViewSlotSnapshot<LAnnotation, Caret> | undefined, next: CodeViewSlotSnapshot<LAnnotation, Caret> | undefined): boolean {
    if (previous == null || next == null) {
        return previous === next;
    }
    if (previous.header !== next.header || previous.footer !== next.footer) {
        return false;
    }
    return areRenderedItemsEqual(previous.items, next.items);
}
function areRenderedItemsEqual<LAnnotation, Caret>(previous: CodeViewRenderedItem<LAnnotation, Caret>[] | undefined, next: CodeViewRenderedItem<LAnnotation, Caret>[] | undefined): boolean {
    if (previous == null || next == null) {
        return previous === next;
    }
    if (previous.length !== next.length) {
        return false;
    }
    for (let index = 0; index < previous.length; index++) {
        const previousItem = previous[index];
        const nextItem = next[index];
        if (previousItem == null ||
            nextItem == null ||
            previousItem.id !== nextItem.id ||
            previousItem.type !== nextItem.type ||
            previousItem.element !== nextItem.element ||
            previousItem.instance !== nextItem.instance ||
            previousItem.version !== nextItem.version) {
            return false;
        }
    }
    return true;
}

import type { MergeConflictRegion } from '../types';
import type { MergeConflictDiffAction } from './parseMergeConflictDiffFromFile';
export function areMergeConflictActionsEqual(a: MergeConflictDiffAction, b: MergeConflictDiffAction): boolean {
    return (a.hunkIndex === b.hunkIndex &&
        a.startContentIndex === b.startContentIndex &&
        a.endContentIndex === b.endContentIndex &&
        a.currentContentIndex === b.currentContentIndex &&
        a.baseContentIndex === b.baseContentIndex &&
        a.incomingContentIndex === b.incomingContentIndex &&
        a.endMarkerContentIndex === b.endMarkerContentIndex &&
        a.conflictIndex === b.conflictIndex &&
        areConflictsEqual(a.conflict, b.conflict));
}
