        a.startLineIndex === b.startLineIndex &&
        a.startLineNumber === b.startLineNumber &&
        a.separatorLineIndex === b.separatorLineIndex &&
        a.separatorLineNumber === b.separatorLineNumber &&
        a.endLineIndex === b.endLineIndex &&
        a.endLineNumber === b.endLineNumber &&
        a.baseMarkerLineIndex === b.baseMarkerLineIndex &&
        a.baseMarkerLineNumber === b.baseMarkerLineNumber);
}

export function areObjectsEqual<T extends object>(objA: T | undefined, objB: T | undefined, omitKeys?: (keyof T)[]): boolean {
    // Lets get out of here early if they are the same or either is undefined
    if (objA === objB || objA == null || objB == null) {
        return objA === objB;
    }
    // Convert array to Set for O(1) lookup
    const omitSet = new Set(omitKeys);
    const keysA = Object.keys(objA) as (keyof T)[];
    const keysBSet = new Set(Object.keys(objB) as (keyof T)[]);
    // Compare keys from objA
    for (const key of keysA) {
        keysBSet.delete(key);
        if (omitSet.has(key)) {
            continue;
        }
        if (!(key in objB) || objA[key] !== objB[key]) {
            return false;
        }
    }
    // If we got any remaining keys that aren't omitted in objB,
    // then we gotta return false
    for (const key of Array.from(keysBSet)) {
        if (!omitSet.has(key)) {
            return false;
        }
    }
    return true;
}

import type { CreatePatchOptionsNonabortable } from 'diff';
import type { CodeViewOptions } from '../components/CodeView';
import type { FileDiffOptions } from '../components/FileDiff';
import type { FileStreamOptions } from '../components/FileStream';
import { DEFAULT_THEMES } from '../constants';
import type { FileOptions } from '../react';
import { areObjectsEqual } from './areObjectsEqual';
import { areThemesEqual } from './areThemesEqual';
type AnyOptions<L, C> = CodeViewOptions<L, C> | FileOptions<L, C> | FileDiffOptions<L, C> | FileStreamOptions | undefined;
export function areOptionsEqual<LAnnotation, Caret>(optionsA: AnyOptions<LAnnotation, Caret>, optionsB: AnyOptions<LAnnotation, Caret>): boolean {
    const themeA = optionsA?.theme ?? DEFAULT_THEMES;
    const themeB = optionsB?.theme ?? DEFAULT_THEMES;
    const diffOptsA = getParseDiffOptions(optionsA);
    const diffOptsB = getParseDiffOptions(optionsB);
    return (areThemesEqual(themeA, themeB) &&
        areObjectsEqual(optionsA, optionsB, [
            'theme',
            'parseDiffOptions' as keyof typeof optionsA,
        ]) &&
        areObjectsEqual(diffOptsA, diffOptsB));
}
function getParseDiffOptions<L, C>(options: AnyOptions<L, C>): CreatePatchOptionsNonabortable | undefined {
    if (options != null && 'parseDiffOptions' in options) {
        return options.parseDiffOptions;
    }
    return undefined;
}

import type { CustomPreProperties, PrePropertiesConfig } from '../types';
export function arePrePropertiesEqual(propsA: PrePropertiesConfig | undefined, propsB: PrePropertiesConfig | undefined): boolean {
    if (propsA == null || propsB == null) {
        return propsA === propsB;
    }
    return (areCustomPropertiesEqual(propsA.customProperties, propsB.customProperties) &&
        propsA.type === propsB.type &&
        propsA.diffIndicators === propsB.diffIndicators &&
        propsA.disableBackground === propsB.disableBackground &&
        propsA.disableLineNumbers === propsB.disableLineNumbers &&
        propsA.overflow === propsB.overflow &&
        propsA.split === propsB.split &&
        propsA.totalLines === propsB.totalLines);
}
const EMPTY_CUSTOM_PROPERTIES: CustomPreProperties = {};
function areCustomPropertiesEqual(customPropertiesA: CustomPreProperties = EMPTY_CUSTOM_PROPERTIES, customPropertiesB: CustomPreProperties = EMPTY_CUSTOM_PROPERTIES): boolean {
    if (customPropertiesA === customPropertiesB) {
        return true;
    }
    const keysA = Object.keys(customPropertiesA);
    const keysB = Object.keys(customPropertiesB);
    if (keysA.length !== keysB.length) {
        return false;
    }
    for (const key of keysA) {
        if (customPropertiesA[key] !== customPropertiesB[key]) {
            return false;
