export async function awaitWithTimeout(callback: () => Promise<unknown>, timeout: number = 300): Promise<void> {
    let timeoutId: ReturnType<typeof setTimeout> | undefined;
    try {
        await Promise.race([
            callback(),
            new Promise<void>((resolve) => {
                timeoutId = setTimeout(resolve, timeout);
            }),
        ]);
    }
    finally {
        if (timeoutId != null) {
            clearTimeout(timeoutId);
        }
    }
}

export function cleanLastNewline(contents: string): string {
    let end = contents.length;
    if (contents.charCodeAt(end - 1) === /* \n */ 10) {
        end--;
        if (contents.charCodeAt(end - 1) === /* \r */ 13) {
            end--;
        }
    }
    return contents.slice(0, end);
}

