import { getExpandedRegion, getLeadingHunkSeparatorLayout, getTrailingExpandedRegion, getTrailingHunkSeparatorLayout, } from './virtualDiffLayout';
export interface ComputeEstimatedDiffHeightsOptions {
    fileDiff: FileDiffMetadata;
    metrics: VirtualFileMetrics;
    disableFileHeader: boolean;
    hunkSeparators: HunkSeparators;
    expandUnchanged: boolean;
    expandedHunks: Map<number, HunkExpansionRegion> | true | undefined;
    collapsedContextThreshold: number;
    canHydratePartialDiff: boolean;
}
export interface EstimatedDiffHeights {
    splitHeight: number;
    unifiedHeight: number;
}
// Computes both split and unified baseline heights from hunk-level metadata so
// callers can avoid replaying the detailed rendered-line iterator.
export function computeEstimatedDiffHeights({ fileDiff, metrics, disableFileHeader, hunkSeparators, expandUnchanged, expandedHunks: configuredExpandedHunks, collapsedContextThreshold, canHydratePartialDiff, }: ComputeEstimatedDiffHeightsOptions): EstimatedDiffHeights {
    let splitHeight = getVirtualFileHeaderRegion(metrics, disableFileHeader);
    let unifiedHeight = splitHeight;
    const expandedHunks = expandUnchanged ? true : configuredExpandedHunks;
    const finalHunkIndex = fileDiff.hunks.length - 1;
    for (let hunkIndex = 0; hunkIndex < fileDiff.hunks.length; hunkIndex++) {
        const hunk = fileDiff.hunks[hunkIndex];
        if (hunk == null) {
            throw new Error('computeEstimatedDiffHeights: invalid hunk index');
        }
        const leadingRegion = getExpandedRegion({
            isPartial: fileDiff.isPartial,
            rangeSize: hunk.collapsedBefore,
            expandedHunks,
            hunkIndex,
            collapsedContextThreshold,
        });
        const leadingExpandedHeight = (leadingRegion.fromStart + leadingRegion.fromEnd) * metrics.lineHeight;
        splitHeight += leadingExpandedHeight;
        unifiedHeight += leadingExpandedHeight;
        if (leadingRegion.collapsedLines > 0) {
            const separatorHeight = getLeadingHunkSeparatorLayout({
                type: hunkSeparators,
                metrics,
                hunkIndex,
                hunkSpecs: hunk.hunkSpecs,
            })?.totalHeight ?? 0;
            splitHeight += separatorHeight;
            unifiedHeight += separatorHeight;
        }
        splitHeight += hunk.splitLineCount * metrics.lineHeight;
        unifiedHeight += hunk.unifiedLineCount * metrics.lineHeight;
        const metadataLineCounts = getNoNewlineMetadataLineCounts(hunk);
        splitHeight += metadataLineCounts.split * metrics.lineHeight;
        unifiedHeight += metadataLineCounts.unified * metrics.lineHeight;
        const trailingRegion = hunkIndex === finalHunkIndex
            ? getTrailingExpandedRegion({
                fileDiff,
                hunkIndex,
                expandedHunks,
                collapsedContextThreshold,
                errorPrefix: 'computeEstimatedDiffHeights',
            })
            : undefined;
        if (trailingRegion != null) {
            const trailingExpandedHeight = (trailingRegion.fromStart + trailingRegion.fromEnd) *
                metrics.lineHeight;
            splitHeight += trailingExpandedHeight;
            unifiedHeight += trailingExpandedHeight;
            if (trailingRegion.collapsedLines > 0) {
                const separatorHeight = getTrailingHunkSeparatorLayout({
                    type: hunkSeparators,
                    metrics,
                })?.totalHeight ?? 0;
                splitHeight += separatorHeight;
                unifiedHeight += separatorHeight;
            }
        }
        else if (hunkIndex === finalHunkIndex &&
            fileDiff.isPartial &&
            canHydratePartialDiff) {
            const separatorHeight = getTrailingHunkSeparatorLayout({
                type: hunkSeparators,
                metrics,
            })?.totalHeight ?? 0;
            splitHeight += separatorHeight;
            unifiedHeight += separatorHeight;
        }
    }
    if (fileDiff.hunks.length > 0) {
        const paddingBottom = getVirtualFilePaddingBottom(metrics);
        splitHeight += paddingBottom;
        unifiedHeight += paddingBottom;
    }
    return { splitHeight, unifiedHeight };
}
function getNoNewlineMetadataLineCounts(hunk: Hunk): {
    split: number;
    unified: number;
} {
    if (!hunk.noEOFCRAdditions && !hunk.noEOFCRDeletions) {
        return { split: 0, unified: 0 };
    }
    const lastContent = hunk.hunkContent.at(-1);
    if (lastContent == null) {
        return { split: 0, unified: 0 };
    }
    if (lastContent.type === 'context') {
        const metadataRows = lastContent.lines > 0 ? 1 : 0;
        return { split: metadataRows, unified: metadataRows };
    }
    return getChangeNoNewlineMetadataLineCounts(hunk, lastContent);
}
function getChangeNoNewlineMetadataLineCounts(hunk: Hunk, content: ChangeContent): {
    split: number;
    unified: number;
} {
    const unified = (content.deletions > 0 && hunk.noEOFCRDeletions ? 1 : 0) +
        (content.additions > 0 && hunk.noEOFCRAdditions ? 1 : 0);
    const splitDeletionHasMetadata = content.deletions > 0 && hunk.noEOFCRDeletions;
    const splitAdditionHasMetadata = content.additions > 0 && hunk.noEOFCRAdditions;
    const split = splitDeletionHasMetadata || splitAdditionHasMetadata ? 1 : 0;
    return { split, unified };
}

const LINE_FEED = 10; // \n
const CARRIAGE_RETURN = 13; // \r
const DENSE_LINE_BREAK_BLOCK_SIZE = 4;
const DENSE_LINE_BREAK_BLOCK_SPAN = 40;
/**
 * Computes line start offsets for a string.
 */
export function computeLineOffsets(contents: string): number[] {
    const offsets: number[] = [0];
    let carriageReturn = contents.indexOf('\r');
    let lineFeed = contents.indexOf('\n');
    let blockStart = 0;
    let blockBreaks = 0;
    while (carriageReturn !== -1 || lineFeed !== -1) {
        let nextOffset: number;
        if (carriageReturn !== -1 &&
            (lineFeed === -1 || carriageReturn < lineFeed)) {
            if (lineFeed === carriageReturn + 1) {
                nextOffset = lineFeed + 1;
                carriageReturn = contents.indexOf('\r', nextOffset);
                lineFeed = contents.indexOf('\n', nextOffset);
            }
            else {
                nextOffset = carriageReturn + 1;
                carriageReturn = contents.indexOf('\r', nextOffset);
            }
        }
        else {
            nextOffset = lineFeed + 1;
            lineFeed = contents.indexOf('\n', nextOffset);
        }
        offsets.push(nextOffset);
        if (++blockBreaks === DENSE_LINE_BREAK_BLOCK_SIZE) {
            if (nextOffset - blockStart <= DENSE_LINE_BREAK_BLOCK_SPAN) {
                // Native searches win on source-like lines; a character scan is faster
                // once line breaks become unusually dense.
                for (let i = nextOffset; i < contents.length; i++) {
                    const char = contents.charCodeAt(i);
                    if (char === LINE_FEED || char === CARRIAGE_RETURN) {
                        if (char === CARRIAGE_RETURN &&
                            i + 1 < contents.length &&
                            contents.charCodeAt(i + 1) === LINE_FEED) {
                            i++;
                        }
                        offsets.push(i + 1);
                    }
                }
                return offsets;
            }
            blockStart = nextOffset;
            blockBreaks = 0;
        }
    }
    return offsets;
}
/**
 * Counts line breaks in a string, treating `\n`, `\r`, and `\r\n` the same way
 * {@link computeLineOffsets} does (a `\r\n` pair is one break). Mirrors that
 * scan but counts in a single pass instead of building and discarding an
 * offsets array, so sizing the changed-line range for large edits stays cheap.
 * A unit test asserts it stays in lockstep with `computeLineOffsets`.
 */
export function countLineBreaks(contents: string): number {
    let count = 0;
    for (let i = 0; i < contents.length; i++) {
        const char = contents.charCodeAt(i);
        if (char === LINE_FEED || char === CARRIAGE_RETURN) {
            // Skip the `\n` of a `\r\n` pair so it counts as one break, not two.
            if (char === CARRIAGE_RETURN &&
                i + 1 < contents.length &&
                contents.charCodeAt(i + 1) === LINE_FEED) {
                i++;
            }
            count++;
        }
    }
    return count;
}
/**
 * Splits file contents into lines aligned with {@link computeLineOffsets}.
 * Unlike splitFileContents, a trailing newline produces a final empty line.
 */
export function linesFromFileContents(contents: string): string[] {
    const offsets = computeLineOffsets(contents);
    const lines = Array.from({ length: offsets.length }, (_, i) => {
        const start = offsets[i];
        const end = offsets[i + 1] ?? contents.length;
        return contents.slice(start, end);
    });
    return lines;
}

import { DEFAULT_VIRTUAL_FILE_METRICS } from '../constants';
