export function getLineEndingType(content: string): 'CRLF' | 'CR' | 'LF' | 'none' {
    // Windows
    if (content.includes('\r\n')) {
        return 'CRLF';
    }
    // Old Mac
    if (content.includes('\r')) {
        return 'CR';
    }
    // Unix/Linux/Modern Mac
    if (content.includes('\n')) {
        return 'LF';
    }
    // No line endings found
    return 'none';
}

import type { ElementContent, Root, RootContent } from 'hast';
export function getLineNodes(nodes: Root): ElementContent[] {
    let firstChild: RootContent | Element | Root | null = nodes.children[0];
    while (firstChild != null) {
        if (firstChild.type === 'element' && firstChild.tagName === 'code') {
            return firstChild.children;
        }
        if ('children' in firstChild) {
            firstChild = firstChild.children[0];
        }
        else {
            firstChild = null;
        }
    }
    console.error(nodes);
    throw new Error('getLineNodes: Unable to find children');
}

