import { MERGE_CONFLICT_BASE_MARKER_REGEX, MERGE_CONFLICT_END_MARKER_REGEX, MERGE_CONFLICT_SEPARATOR_MARKER_REGEX, MERGE_CONFLICT_START_MARKER_REGEX, } from '../constants';
import type { MergeConflictRegion } from '../types';
export type MergeConflictLineType = 'none' | 'marker-start' | 'marker-base' | 'marker-separator' | 'marker-end' | 'current' | 'base' | 'incoming';
type MergeConflictStage = 'current' | 'base' | 'incoming';
interface MergeConflictFrame {
    stage: MergeConflictStage;
    startLineIndex: number;
    baseMarkerLineIndex?: number;
    separatorLineIndex?: number;
}
export interface MergeConflictParseResult {
    lineTypes: MergeConflictLineType[];
    regions: MergeConflictRegion[];
}
function trimLineEnding(line: string): string {
    return line.replace(/(?:\r\n|\n|\r)$/, '');
}
export function getMergeConflictLineTypes(lines: string[]): MergeConflictLineType[] {
    return getMergeConflictParseResult(lines).lineTypes;
}
export function getMergeConflictParseResult(lines: string[]): MergeConflictParseResult {
    return parseMergeConflicts(lines);
}
export function getMergeConflictActionLineNumber(conflict: MergeConflictRegion): number {
    return Math.max(1, conflict.startLineNumber - 1);
}
function parseMergeConflicts(lines: string[]): MergeConflictParseResult {
    const lineTypes = new Array<MergeConflictLineType>(lines.length);
    const stack: MergeConflictFrame[] = [];
    const regions: MergeConflictRegion[] = [];
    for (let index = 0; index < lines.length; index++) {
        const line = trimLineEnding(lines[index]);
        if (MERGE_CONFLICT_START_MARKER_REGEX.test(line)) {
            stack.push({ stage: 'current', startLineIndex: index });
            lineTypes[index] = 'marker-start';
            continue;
        }
        const frame = stack.at(-1);
        if (frame == null) {
            lineTypes[index] = 'none';
            continue;
        }
        if (MERGE_CONFLICT_BASE_MARKER_REGEX.test(line)) {
            frame.stage = 'base';
            frame.baseMarkerLineIndex = index;
            lineTypes[index] = 'marker-base';
            continue;
        }
        if (MERGE_CONFLICT_SEPARATOR_MARKER_REGEX.test(line)) {
            frame.stage = 'incoming';
            frame.separatorLineIndex = index;
            lineTypes[index] = 'marker-separator';
            continue;
        }
        if (MERGE_CONFLICT_END_MARKER_REGEX.test(line)) {
            const completedFrame = stack.pop();
            lineTypes[index] = 'marker-end';
            if (completedFrame?.separatorLineIndex != null) {
                const conflictIndex = regions.length;
                regions.push({
                    conflictIndex,
                    startLineIndex: completedFrame.startLineIndex,
                    startLineNumber: completedFrame.startLineIndex + 1,
                    separatorLineIndex: completedFrame.separatorLineIndex,
                    separatorLineNumber: completedFrame.separatorLineIndex + 1,
                    endLineIndex: index,
                    endLineNumber: index + 1,
                    baseMarkerLineIndex: completedFrame.baseMarkerLineIndex,
                    baseMarkerLineNumber: completedFrame.baseMarkerLineIndex != null
                        ? completedFrame.baseMarkerLineIndex + 1
                        : undefined,
                });
            }
            continue;
        }
        lineTypes[index] = frame.stage;
    }
    return { lineTypes, regions };
}

interface CreateCodeNodeProps {
    pre?: HTMLPreElement;
    code?: HTMLElement;
    columnType?: 'additions' | 'deletions' | 'unified';
    rowSpan?: number;
    containerSize?: boolean;
}
export function getOrCreateCodeNode({ code, pre, columnType, rowSpan, containerSize = false, }: CreateCodeNodeProps = {}): HTMLElement {
    if (code == null) {
        code = document.createElement('code');
        code.setAttribute('data-code', '');
        if (columnType != null) {
            code.setAttribute(`data-${columnType}`, '');
        }
        pre?.appendChild(code);
    }
    if (rowSpan != null) {
        code.style.setProperty('grid-row', `span ${rowSpan}`);
    }
    else {
        code.style.removeProperty('grid-row');
    }
    if (containerSize) {
        code.setAttribute('data-container-size', '');
    }
    else {
        code.removeAttribute('data-container-size');
    }
    return code;
}

import type { FileDiffMetadata } from '../types';
import { parsePatchFiles } from './parsePatchFiles';
export function getSingularPatch(patch: string): FileDiffMetadata {
    const parsedPatches = parsePatchFiles(patch);
    if (parsedPatches.length !== 1) {
        console.error(parsedPatches);
        throw new Error('PatchDiff: Provided patch must include only 1 patch, with 1 diff');
    }
    const { files } = parsedPatches[0];
    if (files.length !== 1) {
        console.error(files);
        throw new Error('FileDiff: Provided patch must contain exactly 1 file diff');
    }
    return files[0];
}

import { DEFAULT_THEMES } from '../constants';
import type { DiffsThemeNames, ThemesType } from '../types';
export function getThemes(theme: DiffsThemeNames | ThemesType = DEFAULT_THEMES): DiffsThemeNames[] {
    const themesArr: DiffsThemeNames[] = [];
    if (typeof theme === 'string') {
        themesArr.push(theme);
    }
    else {
        themesArr.push(theme.dark);
        themesArr.push(theme.light);
    }
    return themesArr;
}

import type { Hunk } from '../types';
import { getHunkSideEndBoundary } from './getHunkSideBoundaries';
export function getTotalLineCountFromHunks(hunks: Hunk[]): number {
    const lastHunk = hunks.at(-1);
    if (lastHunk == null) {
        return 0;
    }
    return Math.max(getHunkSideEndBoundary(lastHunk.additionStart, lastHunk.additionCount), getHunkSideEndBoundary(lastHunk.deletionStart, lastHunk.deletionCount));
}

/**
 * Runs a wholesale code-column rebuild with the pre element's height pinned,
 * working around a WebKit bug (https://bugs.webkit.org/show_bug.cgi?id=308027):
 * when the subtree of a `container-type: inline-size` element is rewritten in
 * bulk (column innerHTML swaps, grid-row span rewrites), WebKit resolves the
 * ancestor scroller's offset against a transiently collapsed interim layout
 * and clamps scrollTop to 0 — the scroller visibly jumps to the top on every
 * edit. Pinning `min-height` keeps that interim layout at full height so the
 * scroll offset survives; the layout read before unpinning is required, since
 * it materializes the interim layout while the pin is active.
 *
 * Both the pin height read and the pinned-layout read force a synchronous
 * layout, so callers own the gating via shouldGuardRebuildScroll: Safari-only,
 * edit-mode-only, and never inside CodeView's batched read/write render pass.
 */
export function guardWebKitScrollDuringRebuild(pre: HTMLElement | undefined, rebuild: () => void): void {
    const height = pre?.offsetHeight ?? 0;
    if (pre == null || height === 0) {
        rebuild();
        return;
    }
    pre.style.minHeight = `${height}px`;
    try {
        rebuild();
        void pre.offsetHeight;
    }
    finally {
        pre.style.minHeight = '';
    }
}

import type { ElementContent, Element as HASTElement, Properties, Root, RootContent, Text, } from 'hast';
