    public isInitialized(): boolean {
        return this.initialized === true;
    }
    public async initialize(languages: SupportedLanguages[] = []): Promise<void> {
        if (this.initialized === true) {
            return;
        }
        else if (this.initialized === false) {
            const { lifecycleGeneration } = this;
            this.initialized = new Promise((resolve, reject) => {
                void (async () => {
                    try {
                        const themes = getThemes(this.renderOptions.theme);
                        let resolvedThemes: ThemeRegistrationResolved[] = [];
                        if (hasResolvedThemes(themes)) {
                            resolvedThemes = getResolvedThemes(themes);
                        }
                        else {
                            resolvedThemes = await resolveThemes(themes);
                        }
                        if (!this.isCurrentLifecycle(lifecycleGeneration)) {
                            resolve();
                            return;
                        }
                        let resolvedLanguages: ResolvedLanguage[] = [];
                        if (hasResolvedLanguages(languages)) {
                            resolvedLanguages = getResolvedLanguages(languages);
                        }
                        else {
                            resolvedLanguages = await resolveLanguages(languages);
                        }
                        if (!this.isCurrentLifecycle(lifecycleGeneration)) {
                            resolve();
                            return;
                        }
                        const [highlighter] = await Promise.all([
                            getSharedHighlighter({
                                themes,
                                langs: ['text', ...languages],
                                preferredHighlighter: this.preferredHighlighter,
                            }),
                            this.initializeWorkers(resolvedThemes, resolvedLanguages),
                        ]);
                        if (!this.isCurrentLifecycle(lifecycleGeneration)) {
                            this.terminateWorkers();
                            resolve();
                            return;
                        }
                        this.highlighter = highlighter;
                        this.initialized = true;
                        this.diffCache.clear();
                        this.fileCache.clear();
                        this.drainQueue();
                        this.queueBroadcastStateChanges();
                        resolve();
                    }
                    catch (e) {
                        if (e instanceof WorkerPoolTerminatedError ||
                            !this.isCurrentLifecycle(lifecycleGeneration)) {
                            resolve();
                            return;
                        }
                        this.initialized = false;
                        this.workersFailed = true;
                        // A partial pool is not supported, so stop every worker before
                        // consumers rerender through the main-thread fallback.
                        this.cancelActiveWorkerTasks();
                        this.terminateWorkers();
                        this.activeTaskById.clear();
                        for (const task of this.queuedTasks) {
                            this.rejectRenderTaskCallbacks(task, normalizeWorkerError(e));
                        }
                        this.queueBroadcastStateChanges();
                        reject(e);
                    }
                })();
            });
            this.queueBroadcastStateChanges();
        }
        else {
            return this.initialized;
        }
    }
    private async initializeWorkers(resolvedThemes: ThemeRegistrationResolved[], resolvedLanguages: ResolvedLanguage[]): Promise<void> {
        this.workersFailed = false;
        const initPromises: Promise<unknown>[] = [];
        const customExtensionVersion = getCustomExtensionsVersion();
        const customExtensionMap = customExtensionVersion > 0 ? getCustomExtensionsMap() : undefined;
        if (this.workers.length > 0) {
            this.terminateWorkers();
        }
        for (let i = 0; i < (this.options.poolSize ?? 8); i++) {
            const worker = this.options.workerFactory();
            const managedWorker: ManagedWorker = {
                worker,
                requestId: undefined,
                pendingSetupRequestId: undefined,
                initialized: false,
                langs: new Set(['text', ...resolvedLanguages.map(({ name }) => name)]),
                customExtensionsVersion: 0,
            };
            worker.addEventListener('message', (event: MessageEvent<WorkerResponse>) => {
                this.handleWorkerMessage(managedWorker, event.data);
            });
            worker.addEventListener('error', (error) => this.handleWorkerError(managedWorker, error));
            this.workers.push(managedWorker);
            initPromises.push(new Promise<void>((resolve, reject) => {
                const id = this.generateRequestId();
                const task: InitializeWorkerTask = {
                    type: 'initialize',
                    id,
                    request: {
                        type: 'initialize',
                        id,
                        renderOptions: this.renderOptions,
                        preferredHighlighter: this.preferredHighlighter,
                        resolvedThemes,
                        resolvedLanguages,
                        customExtensionsVersion: customExtensionMap != null ? customExtensionVersion : undefined,
                        customExtensionMap,
                    },
                    resolve() {
                        managedWorker.initialized = true;
                        resolve();
                    },
                    reject,
                    requestStart: Date.now(),
                };
                managedWorker.pendingSetupRequestId = id;
                this.activeTaskById.set(id, task);
                this.executeTask(managedWorker, task);
            }));
        }
        const timeoutMs = this.options.workerInitializationTimeout ??
            DEFAULT_WORKER_INITIALIZATION_TIMEOUT;
        let timeoutId: ReturnType<typeof setTimeout> | undefined;
        try {
            await Promise.race([
                Promise.all(initPromises),
                new Promise<never>((_, reject) => {
                    timeoutId = setTimeout(() => {
                        reject(new Error(`WorkerPoolManager: worker initialization timed out after ${timeoutMs}ms`));
                    }, timeoutMs);
                }),
            ]);
        }
        finally {
            if (timeoutId != null) {
                clearTimeout(timeoutId);
            }
        }
    }
    private handleWorkerError(managedWorker: ManagedWorker, error: unknown): void {
        console.error('Worker error:', error, managedWorker);
        const { pendingSetupRequestId } = managedWorker;
        if (pendingSetupRequestId == null) {
            return;
        }
        const task = this.activeTaskById.get(pendingSetupRequestId);
        if (task?.type !== 'initialize') {
            return;
        }
        task.reject(normalizeWorkerError(error));
        this.cleanWorkerAndTask(managedWorker, task);
