            return Promise.reject(new Error('WorkerPoolManager.primeFileHighlightCache: worker pool is not working'));
        }
        const task = this.getOrCreateFileHighlightCacheTask(file);
        return task != null
            ? this.createRenderTaskCallbacks(task)
            : Promise.resolve();
    }
    private getOrCreateFileHighlightCacheTask(file: FileContents): RenderFileTask | undefined {
        if (file.cacheKey == null) {
            console.warn(`WorkerPoolManager.primeFileHighlightCache: priming highlight cache requires file.cacheKey; skipping "${file.name}".`);
            return undefined;
        }
        const cachedResult = this.getFileResultCache(file);
        const highlightKey = this.getFileHighlightKey(file);
        if (highlightKey == null ||
            isFilePlainText(file) ||
            (cachedResult != null &&
                areFileRenderOptionsEqual(cachedResult.options, this.getFileRenderOptions()))) {
            return undefined;
        }
        const existingTask = this.getTaskByHighlightKey(highlightKey);
        if (existingTask != null) {
            existingTask.primeCache = true;
            return existingTask.type === 'file' ? existingTask : undefined;
        }
        else {
            const task = this.submitCacheTask({ type: 'file', file }, highlightKey);
            return task.type === 'file' ? task : undefined;
