            this.queueInitialization();
            return undefined;
        }
        return renderFileWithHighlighter(file, this.highlighter, this.renderOptions, { forcePlainText: true, startingLine, totalLines, lines });
    }
    public highlightDiffAST(instance: DiffRendererInstance, diff: FileDiffMetadata): void {
