            return Promise.reject(new Error('WorkerPoolManager.primeDiffHighlightCache: worker pool is not working'));
        }
        const task = this.getOrCreateDiffHighlightCacheTask(diff);
        return task != null
            ? this.createRenderTaskCallbacks(task)
            : Promise.resolve();
    }
    private getOrCreateDiffHighlightCacheTask(diff: FileDiffMetadata): RenderDiffTask | undefined {
