    public getPlainDiffAST(diff: FileDiffMetadata, startingLine: number, totalLines: number, expandedHunks?: Map<number, HunkExpansionRegion> | true, collapsedContextThreshold?: number): ThemedDiffResult | undefined {
        return this.highlighter != null
            ? renderDiffWithHighlighter(diff, this.highlighter, this.renderOptions, {
                forcePlainText: true,
                startingLine,
                totalLines,
                expandedHunks,
                collapsedContextThreshold,
            })
            : undefined;
    }
    public terminate(): void {
