            managedWorker.worker.terminate();
        }
        this.workers.length = 0;
    }
    public getStats(): WorkerStats {
        return {
            managerState: (() => {
                if (this.initialized === false) {
                    return 'waiting';
                }
                if (this.initialized !== true) {
                    return 'initializing';
                }
                return 'initialized';
            })(),
            totalWorkers: this.workers.length,
            workersFailed: this.workersFailed,
            busyWorkers: this.workers.filter((w) => w.requestId != null || w.pendingSetupRequestId != null).length,
            queuedTasks: this.queuedTasks.length,
            activeTasks: this.activeTaskById.size,
            themeSubscribers: this.themeSubscribers.size,
            fileCacheSize: this.fileCache.size,
            diffCacheSize: this.diffCache.size,
        };
    }
    private submitTask(instance: FileRendererInstance, request: Omit<RenderFileRequest, 'id'>): void;
    private submitTask(instance: DiffRendererInstance, request: Omit<RenderDiffRequest, 'id'>): void;
    private submitTask(instance: FileRendererInstance | DiffRendererInstance, request: SubmitRequest): void {
        if (this.initialized === false) {
            this.queueInitialization();
        }
        const highlightKey = this.getHighlightKeyForRequest(request);
        const existingTask = highlightKey != null
            ? this.getTaskByHighlightKey(highlightKey)
            : undefined;
        if (existingTask != null) {
            this.detachInstanceFromQueuedTasks(instance, existingTask);
            this.addInstanceToTask(existingTask, instance);
            this.queueBroadcastStateChanges();
            return;
        }
        this.detachInstanceFromQueuedTasks(instance);
        const id = this.generateRequestId();
        const requestStart = Date.now();
        const { renderOptionsVersion } = this;
        const task: RenderTask = (() => {
            switch (request.type) {
                case 'file':
                    return {
                        type: 'file',
                        id,
                        request: { ...request, id },
                        instances: new Set([instance as FileRendererInstance]),
                        primeCache: false,
                        highlightKey,
                        callbacks: new Set(),
                        renderOptionsVersion,
                        requestStart,
                    };
                case 'diff':
                    return {
                        type: 'diff',
                        id,
                        request: { ...request, id },
                        instances: new Set([instance as DiffRendererInstance]),
                        primeCache: false,
                        highlightKey,
                        callbacks: new Set(),
                        renderOptionsVersion,
                        requestStart,
                    };
            }
        })();
        this.enqueueRenderTask(task, instance);
    }
    private submitCacheTask(request: SubmitRequest, highlightKey: string): RenderTask {
        if (this.initialized === false) {
            this.queueInitialization();
        }
        const id = this.generateRequestId();
        const requestStart = Date.now();
        const { renderOptionsVersion } = this;
        const task: RenderTask = (() => {
            switch (request.type) {
                case 'file':
                    return {
                        type: 'file',
                        id,
                        request: { ...request, id },
                        instances: new Set<FileRendererInstance>(),
                        primeCache: true,
                        highlightKey,
                        callbacks: new Set(),
                        renderOptionsVersion,
                        requestStart,
                    };
                case 'diff':
                    return {
                        type: 'diff',
                        id,
                        request: { ...request, id },
                        instances: new Set<DiffRendererInstance>(),
                        primeCache: true,
                        highlightKey,
                        callbacks: new Set(),
                        renderOptionsVersion,
                        requestStart,
                    };
            }
        })();
        this.enqueueRenderTask(task);
        return task;
    }
    private enqueueRenderTask(task: RenderTask, instance?: RenderTaskInstance): void {
